insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('energy-spending-and-refilling-week-planner', 'Energy Spending and Refilling Week Planner', 'worksheet'::resource_kind, 'A one-page planner for spending and refilling energy across a week of activities.', 'Use it to help a client see where energy goes and plan realistic rest.', array['Adults']::text[], '20 minutes', 'Have the client list the week''s commitments and rate how draining or refilling each feels, then look together for days that are overbooked. The planner is a conversation starter, not a verdict; let the client decide what to move, drop or protect, and revisit it next session.', '[{"id": "f0", "type": "textarea", "label": "The activities that take the most energy this week"}, {"id": "f1", "type": "textarea", "label": "The activities that give energy back"}, {"id": "f2", "type": "textarea", "label": "A day that looks overbooked"}, {"id": "f3", "type": "textarea", "label": "One thing I could move, shorten or drop"}, {"id": "f4", "type": "textarea", "label": "One refill I will protect this week"}]'::jsonb, array['planning', 'routines', 'stress']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('values-based-weekly-calendar-review', 'Values-Based Weekly Calendar Review', 'worksheet'::resource_kind, 'A calendar review that compares how a client spent their week with what matters to them.', 'Use it to help a client notice gaps between their time and their stated values.', array['Adults']::text[], '25 minutes', 'Ask the client to bring their real calendar and name two or three values before filling in the sheet. Look for matches and gaps without judgment; the aim is a small adjustment the client chooses, not a perfect schedule. Keep the changes small enough to try this week.', '[{"id": "f0", "type": "textarea", "label": "Two or three things that matter most to me"}, {"id": "f1", "type": "textarea", "label": "Where my week matched them"}, {"id": "f2", "type": "textarea", "label": "Where my week did not match them"}, {"id": "f3", "type": "textarea", "label": "One small change I am willing to try"}, {"id": "f4", "type": "textarea", "label": "How I will know I tried it"}]'::jsonb, array['values', 'planning', 'goal setting']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('weekend-reset-menu-builder', 'Weekend Reset Menu Builder', 'worksheet'::resource_kind, 'A menu a client builds of restful, social and useful things to choose from on days off.', 'Use it to help a client plan days off so they feel restored rather than drained.', array['Adults']::text[], '20 minutes', 'Have the client sort ideas into rest, connection and useful chores, then choose one from each column for the coming weekend. Look at whether the plan leaves any open time. Clients often over-schedule days off or leave them empty; ask what restores them and let them adjust the plan.', '[{"id": "f0", "type": "textarea", "label": "Things that help me rest"}, {"id": "f1", "type": "textarea", "label": "Things that help me connect with others"}, {"id": "f2", "type": "textarea", "label": "Chores I would like off my list"}, {"id": "f3", "type": "textarea", "label": "My picks for this weekend"}, {"id": "f4", "type": "textarea", "label": "What I will do if the plan falls apart"}]'::jsonb, array['planning', 'routines', 'self-care']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('small-wins-capture-log', 'Small Wins Capture Log', 'worksheet'::resource_kind, 'A daily log for recording small things that went right, however minor.', 'Use it to help a client build the habit of noticing progress that is easy to overlook.', array['Adults']::text[], 'Five minutes daily for two weeks', 'Introduce it as a place to write the ordinary, not the impressive: a call returned, a walk taken, a hard moment handled a little differently. Review the log together and ask what the client''s wins say about what they can do. Keep the entries short so the habit stays easy.', '[{"id": "f0", "type": "textarea", "label": "Today''s small win"}, {"id": "f1", "type": "textarea", "label": "What I did to make it happen"}, {"id": "f2", "type": "textarea", "label": "Who or what helped"}, {"id": "f3", "type": "textarea", "label": "What it tells me about myself"}, {"id": "f4", "type": "textarea", "label": "The win I would like to repeat tomorrow"}]'::jsonb, array['strengths', 'monitoring', 'routines']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('ten-ten-ten-decision-timeline-sheet', 'Ten-Ten-Ten Decision Timeline Sheet', 'worksheet'::resource_kind, 'A timeline sheet that asks how a choice will feel in ten minutes, ten months and ten years.', 'Use it to help a client look past the pull of the moment when making a choice.', array['Adults']::text[], '20 minutes', 'Name the decision and have the client write how each option is likely to feel at each time frame. Differences across the three often show the pull of short-term relief. Let the client decide in their own time; the sheet is a way to see the choice from further away.', '[{"id": "f0", "type": "textarea", "label": "The decision I am facing"}, {"id": "f1", "type": "textarea", "label": "How each option feels in ten minutes"}, {"id": "f2", "type": "textarea", "label": "How each option may feel in ten months"}, {"id": "f3", "type": "textarea", "label": "How each option may feel in ten years"}, {"id": "f4", "type": "textarea", "label": "What I notice looking across all three"}]'::jsonb, array['decisions', 'perspective', 'planning']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('rigid-rules-to-flexible-preferences-rewrite', 'Rigid Rules to Flexible Preferences Rewrite', 'cbt'::resource_kind, 'A sheet for turning must and should rules into preferences that leave room for exceptions.', 'Use it to help a client loosen rules about themselves that leave no room for being human.', array['Adults']::text[], '25 minutes', 'The client writes rules they hold, such as I must never make mistakes, and rewrites each as a preference, such as I would like to do well and I can recover when I do not. Ask what the rule is meant to protect and what it costs. Practice the rewrite on a recent event.', '[{"id": "f0", "type": "textarea", "label": "A rule I hold for myself"}, {"id": "f1", "type": "textarea", "label": "What the rule is meant to protect"}, {"id": "f2", "type": "textarea", "label": "What it costs me"}, {"id": "f3", "type": "textarea", "label": "The same rule as a preference"}, {"id": "f4", "type": "textarea", "label": "How I will use the new version this week"}]'::jsonb, array['core CBT', 'belief change', 'thinking traps']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('prediction-tally-weekly-scoreboard', 'Prediction Tally Weekly Scoreboard', 'cbt'::resource_kind, 'A scoreboard where a client tallies predictions against what actually happened.', 'Use it to help a client see over time how often predicted outcomes come true.', array['Adults']::text[], 'One week', 'Each day the client writes a prediction, what happened and a tick for whether it came true. At the end of the week add up the ticks. The tally is a way to look at the pattern, and clients are often surprised. Discuss which predictions were closest and why.', '[{"id": "f0", "type": "textarea", "label": "Today''s prediction"}, {"id": "f1", "type": "textarea", "label": "What actually happened"}, {"id": "f2", "type": "textarea", "label": "Did it come true? Yes, partly or no"}, {"id": "f3", "type": "textarea", "label": "Which predictions were closest"}, {"id": "f4", "type": "textarea", "label": "What the tally tells me this week"}]'::jsonb, array['core CBT', 'evidence', 'monitoring']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('cognitive-flexibility-perspective-wheel', 'Cognitive Flexibility Perspective Wheel', 'cbt'::resource_kind, 'A wheel of other viewpoints a client can try on in a stuck moment.', 'Use it to help a client generate more than one reading of a situation.', array['Adults']::text[], '20 minutes', 'Draw a circle with spokes for viewpoints such as a friend, a future self, a neutral observer and someone who cares about the client. The client writes how each might read the same event. The goal is more options, not a correct answer; ask which viewpoint feels most useful and why.', '[{"id": "f0", "type": "textarea", "label": "The situation and my first reading of it"}, {"id": "f1", "type": "textarea", "label": "How a good friend might see it"}, {"id": "f2", "type": "textarea", "label": "How I might see it a year from now"}, {"id": "f3", "type": "textarea", "label": "How a neutral observer might see it"}, {"id": "f4", "type": "textarea", "label": "The reading I want to keep in mind"}]'::jsonb, array['core CBT', 'perspective', 'thinking traps']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('worry-time-appointment-tracker', 'Worry Time Appointment Tracker', 'cbt'::resource_kind, 'A tracker for postponing worries to a set daily appointment and reviewing them there.', 'Use it to help a client practice setting worries aside until a chosen time.', array['Adults']::text[], 'One week', 'Agree on a fifteen-minute window that is not near bedtime. Through the day the client jots a few words for each worry and returns to what they were doing; at the appointment they read the list and sort which worries need a step. Expect the first days to feel awkward.', '[{"id": "f0", "type": "textarea", "label": "The time I chose for worry time"}, {"id": "f1", "type": "textarea", "label": "Worries I wrote down today in a few words"}, {"id": "f2", "type": "textarea", "label": "Which ones still matter at worry time"}, {"id": "f3", "type": "textarea", "label": "A step I can take on one of them"}, {"id": "f4", "type": "textarea", "label": "What happened when I postponed a worry"}]'::jsonb, array['core CBT', 'worry', 'self-monitoring']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('pre-event-rumination-interrupt-sheet', 'Pre-Event Rumination Interrupt Sheet', 'cbt'::resource_kind, 'A sheet for noticing and redirecting rehearsing and replaying before a feared event.', 'Use it to help a client shift attention from rehearsing worries to the task ahead.', array['Adults']::text[], '20 minutes', 'The client lists what they replay or rehearse before an event, what it does for them and what it costs in time and mood. Then they choose a task-focused activity to switch to and a time limit. Practice the switch in session with a recent example and review how it went.', '[{"id": "f0", "type": "textarea", "label": "What I replay or rehearse before an event"}, {"id": "f1", "type": "textarea", "label": "What it does for me"}, {"id": "f2", "type": "textarea", "label": "What it costs me"}, {"id": "f3", "type": "textarea", "label": "What I can switch to instead"}, {"id": "f4", "type": "textarea", "label": "My time limit for rehearsing"}]'::jsonb, array['core CBT', 'worry', 'attention']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('compass-and-weather-report-values-page', 'Compass and Weather Report Values Page', 'act'::resource_kind, 'A page that treats feelings as weather and values as a compass for the day''s direction.', 'Use it to help a client keep heading toward their values whatever the inner weather.', array['Adults']::text[], '25 minutes', 'The client describes today''s inner weather and then the compass direction they want to travel. Ask what they can do in rain that still points the same way. Weather changes whether or not it is acted on; the compass stays steady. Revisit it each session.', '[{"id": "f0", "type": "textarea", "label": "Today''s inner weather"}, {"id": "f1", "type": "textarea", "label": "My compass direction"}, {"id": "f2", "type": "textarea", "label": "What the weather tells me to do"}, {"id": "f3", "type": "textarea", "label": "What I can do that points my compass way"}, {"id": "f4", "type": "textarea", "label": "A small step for today"}]'::jsonb, array['core ACT', 'values', 'metaphor']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('thought-radio-volume-exercise', 'Thought Radio Volume Exercise', 'act'::resource_kind, 'An exercise that treats thoughts as background radio the client can turn down but not off.', 'Use it to help a client notice thoughts as sounds while they get on with what matters.', array['Adults']::text[], '15 minutes', 'Ask the client to imagine a radio that plays their thoughts and to give it a station name. Have them do a small task with the radio playing. Notice that they can act without turning the radio off. Ask what the radio says most and how it might sound with a silly voice.', '[{"id": "f0", "type": "textarea", "label": "The name of my thought radio station"}, {"id": "f1", "type": "textarea", "label": "What it plays most often"}, {"id": "f2", "type": "textarea", "label": "What I did with it playing in the background"}, {"id": "f3", "type": "textarea", "label": "What changed when I gave it a silly voice"}, {"id": "f4", "type": "textarea", "label": "Where I could use this this week"}]'::jsonb, array['core ACT', 'defusion', 'metaphor']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('values-ruler-rating-page', 'Values Ruler Rating Page', 'act'::resource_kind, 'A page where a client rates how closely each area of life matches their values.', 'Use it to help a client spot where actions and values are furthest apart.', array['Adults']::text[], '25 minutes', 'The client picks several life areas, such as family, work, health and friends, writes how much each matters and how closely they have lived it this week. The gap is where to put small steps. Do not use it to grade the client; it shows where to look first.', '[{"id": "f0", "type": "textarea", "label": "Life areas that matter to me"}, {"id": "f1", "type": "textarea", "label": "How much each matters, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How closely I lived it this week, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "The area with the biggest gap"}, {"id": "f4", "type": "textarea", "label": "One small step for that area"}]'::jsonb, array['core ACT', 'values', 'monitoring']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('mindful-dishwashing-everyday-task-practice', 'Mindful Dishwashing Everyday Task Practice', 'act'::resource_kind, 'A practice of bringing full attention to one ordinary task such as washing dishes.', 'Use it to help a client practice present-moment attention in daily life.', array['Adults']::text[], 'One week', 'Choose a routine task and have the client notice the temperature, the sounds and the movements for a few minutes, and bring attention back when it drifts. The practice is about the returning. Review what pulled them away and what they noticed.', '[{"id": "f0", "type": "textarea", "label": "The task I chose"}, {"id": "f1", "type": "textarea", "label": "What I noticed through my senses"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f3", "type": "textarea", "label": "How I brought it back"}, {"id": "f4", "type": "textarea", "label": "Another task I could try"}]'::jsonb, array['core ACT', 'mindfulness', 'routines']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('obstacle-cards-for-valued-plans', 'Obstacle Cards for Valued Plans', 'act'::resource_kind, 'A set of cards pairing likely obstacles with ways to carry on toward a valued goal.', 'Use it to help a client expect the obstacles that come between a plan and action.', array['Adults']::text[], '25 minutes', 'Name the valued action and have the client write cards for the obstacles inside them, such as thoughts and feelings, and outside, such as time and tiredness, each with a way to carry on. Rehearse one card aloud and agree on when it will be tried.', '[{"id": "f0", "type": "textarea", "label": "The valued action I plan"}, {"id": "f1", "type": "textarea", "label": "An obstacle inside me"}, {"id": "f2", "type": "textarea", "label": "How I will carry on with it"}, {"id": "f3", "type": "textarea", "label": "An obstacle outside me"}, {"id": "f4", "type": "textarea", "label": "How I will deal with that one"}]'::jsonb, array['core ACT', 'committed action', 'planning']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('apologizing-without-over-apologizing-script', 'Apologizing Without Over-Apologizing Script', 'dbt'::resource_kind, 'A script for a short, honest apology that does not take on blame that is not the client''s.', 'Use it to help a client apologize clearly when it is warranted, and stop when it is not.', array['Adults']::text[], '25 minutes', 'Have the client sort things they apologize for into those that are theirs and those that are not. For the first group, write a short apology: what happened, my part and what I will do. For the second, practice other phrases. Role-play a few.', '[{"id": "f0", "type": "textarea", "label": "Something I tend to apologize for"}, {"id": "f1", "type": "textarea", "label": "Is it mine to apologize for?"}, {"id": "f2", "type": "textarea", "label": "A short apology with my part and what I will do"}, {"id": "f3", "type": "textarea", "label": "A phrase to use when it is not mine"}, {"id": "f4", "type": "textarea", "label": "Who I will practice with"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'assertiveness']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('check-the-facts-emotion-review', 'Check the Facts Emotion Review', 'dbt'::resource_kind, 'A review sheet that separates the facts of an event from the story and feeling attached to it.', 'Use it to help a client see whether an emotion fits the facts of what happened.', array['Adults']::text[], '20 minutes', 'Have the client name the emotion, the event that set it off, and the interpretation they made, then look at which parts are observable facts. Ask whether the intensity matches the facts. Do not rush to say the feeling is wrong; validate it first, then look at the facts.', '[{"id": "f0", "type": "textarea", "label": "The emotion and how strong it is, 0 to 100"}, {"id": "f1", "type": "textarea", "label": "The event that set it off, only the facts"}, {"id": "f2", "type": "textarea", "label": "The story I told myself about it"}, {"id": "f3", "type": "textarea", "label": "Facts that fit the story and facts that do not"}, {"id": "f4", "type": "textarea", "label": "Whether my emotion still fits the facts"}]'::jsonb, array['core DBT', 'emotion regulation', 'evidence']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('coping-ahead-for-hard-acceptance-moments-card', 'Coping Ahead for Hard Acceptance Moments Card', 'dbt'::resource_kind, 'A card for rehearsing in advance how to accept a hard moment you cannot change.', 'Use it to help a client picture a hard moment and rehearse accepting it.', array['Adults']::text[], '20 minutes', 'The client names a situation ahead that they cannot change, writes what will be hard, and rehearses in imagination how they will accept and cope, with a skill for each step. Practice once in session and adjust after the real event.', '[{"id": "f0", "type": "textarea", "label": "A situation ahead I cannot change"}, {"id": "f1", "type": "textarea", "label": "What will be hardest"}, {"id": "f2", "type": "textarea", "label": "How I will accept it in the moment"}, {"id": "f3", "type": "textarea", "label": "The skill I will use"}, {"id": "f4", "type": "textarea", "label": "How I will care for myself afterward"}]'::jsonb, array['core DBT', 'radical acceptance', 'planning']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('vacation-in-the-mind-imagery-card', 'Vacation in the Mind Imagery Card', 'dbt'::resource_kind, 'A card for building a short imagined getaway with sensory detail.', 'Use it to help a client take a mental break from distress.', array['Adults']::text[], '20 minutes', 'Have the client choose a place, real or imagined, and describe it by sight, sound, smell and touch. Practice a two-minute visit in session and rate distress before and after. If imagery brings up unwanted material, switch to something external. Keep a written script they can read.', '[{"id": "f0", "type": "textarea", "label": "The place I chose"}, {"id": "f1", "type": "textarea", "label": "What I see there"}, {"id": "f2", "type": "textarea", "label": "What I hear and smell"}, {"id": "f3", "type": "textarea", "label": "What I feel there"}, {"id": "f4", "type": "textarea", "label": "Distress before and after, 0 to 10"}]'::jsonb, array['core DBT', 'self-soothing', 'distress tolerance']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('dialectics-both-and-reframing-sheet', 'Dialectics Both-And Reframing Sheet', 'dbt'::resource_kind, 'A sheet for holding two seemingly opposite truths at once instead of picking a side.', 'Use it to help a client loosen all-or-nothing thinking by finding the both-and.', array['Adults']::text[], '20 minutes', 'Have the client write a stuck either-or statement and then rewrite it with and. For example, I am doing my best and I want to do better. Explore how it feels to hold both. Clients who feel invalidated by the rewrite may need the first side acknowledged on its own before the second is added.', '[{"id": "f0", "type": "textarea", "label": "The either-or thought I keep having"}, {"id": "f1", "type": "textarea", "label": "Two things that can both be true"}, {"id": "f2", "type": "textarea", "label": "How the both-and feels in my body"}, {"id": "f3", "type": "textarea", "label": "What changes if I hold both"}, {"id": "f4", "type": "textarea", "label": "A both-and I can remind myself of this week"}]'::jsonb, array['core DBT', 'dialectics', 'thinking traps']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('weekly-state-of-the-home-check-in', 'Weekly State of the Home Check-In', 'couples'::resource_kind, 'A short weekly check-in where both partners share what is working and what needs attention.', 'Use it to give partners a predictable time to talk about the relationship calmly.', array['Couples']::text[], '30 minutes weekly', 'Each partner fills in the sheet alone, then they take turns reading answers while the other listens without rebutting. Start with appreciations. Coach them to keep one request each, phrased as something to do, and to stop at the agreed time even if topics are left over.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciated this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: something I appreciated this week"}, {"id": "f2", "type": "textarea", "label": "Partner A: one request for the coming week"}, {"id": "f3", "type": "textarea", "label": "Partner B: one request for the coming week"}, {"id": "f4", "type": "textarea", "label": "Together: what we will try before next check-in"}]'::jsonb, array['couples', 'communication', 'appreciation']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('complaint-versus-criticism-sorting-cards', 'Complaint Versus Criticism Sorting Cards', 'couples'::resource_kind, 'Cards that sort statements into complaints about an action and criticisms of a person.', 'Use it to help partners tell the two apart and aim for a complaint.', array['Couples']::text[], '25 minutes', 'Write statements on cards, such as you never help versus I felt alone with the dishes, and sort them into complaint or criticism. Then each partner rewrites a recent criticism as a complaint. Discuss how each version lands.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a criticism I have made"}, {"id": "f1", "type": "textarea", "label": "Partner A: my rewrite as a complaint"}, {"id": "f2", "type": "textarea", "label": "Partner B: a criticism I have made"}, {"id": "f3", "type": "textarea", "label": "Partner B: my rewrite as a complaint"}, {"id": "f4", "type": "textarea", "label": "What changed when we heard them"}]'::jsonb, array['couples', 'Gottman', 'communication']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('make-up-plan-after-a-fight', 'Make-Up Plan After a Fight', 'couples'::resource_kind, 'A plan for what partners do in the hours after a fight to reconnect.', 'Use it to help partners recover after a fight and learn from it.', array['Couples']::text[], '30 minutes', 'Partners write what each needs after a fight, such as space, a hug or an apology, and how long. They agree on a way to reconnect and to talk it through when calm, including what each felt and what each would do differently. Use it after a real argument.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need after a fight"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need after a fight"}, {"id": "f2", "type": "textarea", "label": "How we will reconnect"}, {"id": "f3", "type": "textarea", "label": "What each of us felt in the fight"}, {"id": "f4", "type": "textarea", "label": "What we would each do differently"}]'::jsonb, array['couples', 'repair', 'conflict']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('couple-mission-statement-workshop', 'Couple Mission Statement Workshop', 'couples'::resource_kind, 'A workshop for partners to write a short statement of what their life together is for.', 'Use it to help partners name shared purpose and values.', array['Couples']::text[], '45 minutes', 'Each partner writes what they hope the relationship stands for, then they compare lists and draft two or three sentences together. Let it be loose and revisable. Ask what they could do this month to live the statement.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I hope our relationship stands for"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I hope our relationship stands for"}, {"id": "f2", "type": "textarea", "label": "Our statement in two or three sentences"}, {"id": "f3", "type": "textarea", "label": "What we can do this month to live it"}, {"id": "f4", "type": "textarea", "label": "When we will read it again"}]'::jsonb, array['couples', 'values', 'connection']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('six-minute-daily-debrief-talk', 'Six-Minute Daily Debrief Talk', 'couples'::resource_kind, 'A short daily talk where partners take turns telling about their day while the other listens.', 'Use it to help partners keep up with each other''s lives.', array['Couples']::text[], 'Six minutes daily', 'Each partner gets three minutes to talk about their day while the other listens, asks open questions and does not solve. The aim is connection, not advice. Pick a regular time and place, and review after a week how it felt.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the part of my day I shared"}, {"id": "f1", "type": "textarea", "label": "Partner B: the part of my day I shared"}, {"id": "f2", "type": "textarea", "label": "A question I asked that helped"}, {"id": "f3", "type": "textarea", "label": "What was hard about listening"}, {"id": "f4", "type": "textarea", "label": "When and where we will do this"}]'::jsonb, array['couples', 'listening', 'connection']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('feelings-color-wheel-mobile-craft', 'Feelings Color Wheel Mobile Craft', 'kids'::resource_kind, 'A hanging mobile where each color stands for a feeling the child picks.', 'Use it to help a child match feelings with colors and shapes.', array['Children']::text[], '35 minutes', 'The child cuts shapes in colors they pick for feelings and hangs them from a hanger. Talk about what each color means and when they felt it. The parent points to a color to ask how things are, and accepts any answer. Keep it playful.', '[{"id": "f0", "type": "textarea", "label": "The color I picked for happy and why"}, {"id": "f1", "type": "textarea", "label": "The color I picked for sad"}, {"id": "f2", "type": "textarea", "label": "The color for another feeling"}, {"id": "f3", "type": "textarea", "label": "The color I feel most today"}, {"id": "f4", "type": "textarea", "label": "Who I can show my mobile to"}]'::jsonb, array['children', 'emotion identification', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('worry-rock-pocket-craft', 'Worry Rock Pocket Craft', 'kids'::resource_kind, 'A small painted rock a child holds to set a worry down.', 'Use it to give a child something to hold while they name a worry and let go.', array['Children']::text[], '30 minutes', 'The child paints a rock, names it and tells it a worry before bed or at school. The parent hears it, and then the rock goes on a shelf until morning. The goal is to name and put down, not to solve. Replace the rock with a smaller one in a pocket if useful.', '[{"id": "f0", "type": "textarea", "label": "How I painted my worry rock"}, {"id": "f1", "type": "textarea", "label": "A worry I told it"}, {"id": "f2", "type": "textarea", "label": "How I felt after telling it"}, {"id": "f3", "type": "textarea", "label": "Where my rock sleeps"}, {"id": "f4", "type": "textarea", "label": "Who I can tell when I have a worry"}]'::jsonb, array['children', 'worry', 'art', 'play']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('brave-moments-picture-frame-craft', 'Brave Moments Picture Frame Craft', 'kids'::resource_kind, 'A frame a child decorates around a drawing of a brave thing they did.', 'Use it to help a child hold on to brave moments they can look back at.', array['Children']::text[], '30 minutes', 'The child decorates a frame and draws or pastes a picture of something brave they did. The parent writes the child''s words underneath. Add new pictures over time and ask the child to look at it before a hard thing.', '[{"id": "f0", "type": "textarea", "label": "The brave thing in my picture"}, {"id": "f1", "type": "textarea", "label": "How I felt before and after"}, {"id": "f2", "type": "textarea", "label": "What helped me do it"}, {"id": "f3", "type": "textarea", "label": "What I wrote under the picture"}, {"id": "f4", "type": "textarea", "label": "Another brave thing I want to add"}]'::jsonb, array['children', 'exposure', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('bubble-blowing-slow-breath-play', 'Bubble Blowing Slow Breath Play', 'kids'::resource_kind, 'A play session where a child blows bubbles slowly to practice long, slow breaths.', 'Use it to teach a child slow breathing through play.', array['Children']::text[], '20 minutes', 'Blow bubbles together, noticing that slow breaths make big bubbles and fast ones pop them. Count breaths and talk about when slow breaths could help. The parent practices at calm times, not only in upset moments.', '[{"id": "f0", "type": "textarea", "label": "How I blew my biggest bubble"}, {"id": "f1", "type": "textarea", "label": "What my body felt like"}, {"id": "f2", "type": "textarea", "label": "When slow breaths could help"}, {"id": "f3", "type": "textarea", "label": "Who blows bubbles with me"}, {"id": "f4", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['children', 'regulation', 'breathing', 'play']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('kind-words-superhero-cape-craft', 'Kind Words Superhero Cape Craft', 'kids'::resource_kind, 'A decorated cape covered in kind and brave words the child chooses.', 'Use it to help a child collect and wear the good things they and others see in them.', array['Children']::text[], '35 minutes', 'The child decorates a cloth or paper cape with their superhero name and words for their strengths, adding words the parent or friend offers. At home the parent adds a new word when they notice effort. Keep the focus on actions and character. Let the child wear it at the start of the next session.', '[{"id": "f0", "type": "textarea", "label": "My superhero name"}, {"id": "f1", "type": "textarea", "label": "Words for what I am good at"}, {"id": "f2", "type": "textarea", "label": "Words my family says about me"}, {"id": "f3", "type": "textarea", "label": "Words I want to add"}, {"id": "f4", "type": "textarea", "label": "When I will wear my cape"}]'::jsonb, array['children', 'strengths', 'self-esteem', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('emotion-charades-round-robin', 'Emotion Charades Round Robin', 'game'::resource_kind, 'A charades game where players act out feelings and guess them.', 'Use it to help a group practice reading and naming feelings from face and body.', array['Groups']::text[], '25 minutes', 'Write feelings on cards. Each player draws one, acts it out without speaking, and others guess, then everyone says one time they felt it. Rotate turns and let players pass. Debrief which feelings were easy or hard to read and what helped them guess.', '[{"id": "f0", "type": "textarea", "label": "A feeling that was easy to act out"}, {"id": "f1", "type": "textarea", "label": "A feeling that was hard to guess"}, {"id": "f2", "type": "textarea", "label": "A clue in the body that told me what someone felt"}, {"id": "f3", "type": "textarea", "label": "A time I felt one of these"}, {"id": "f4", "type": "textarea", "label": "What I learned from playing"}]'::jsonb, array['group', 'play', 'emotion identification']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('skill-bingo-for-group-practice', 'Skill Bingo for Group Practice', 'game'::resource_kind, 'A bingo card of coping skills the group marks off as they try them.', 'Use it to give a group a playful reason to practice skills between sessions.', array['Groups']::text[], '30 minutes', 'Give each player a card of skills, such as paced breathing, a short walk or naming five things they see. Players mark a square when they try one during the week and share a line about it. Offer a small prize for sharing, not for a full card, so no one feels behind.', '[{"id": "f0", "type": "textarea", "label": "The skill I tried first"}, {"id": "f1", "type": "textarea", "label": "What happened when I tried it"}, {"id": "f2", "type": "textarea", "label": "A skill I skipped and why"}, {"id": "f3", "type": "textarea", "label": "A skill I want to try next"}, {"id": "f4", "type": "textarea", "label": "What I would tell someone starting the card"}]'::jsonb, array['group', 'play', 'skills']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-debate-team-game', 'Pros and Cons Debate Team Game', 'game'::resource_kind, 'A game where two teams argue the pros or cons of a choice and then switch sides.', 'Use it to help players see both sides of a decision in a playful way.', array['Groups']::text[], '30 minutes', 'Pick a small made-up decision. One team argues for, the other against, then they swap. Debrief which arguments stood out and whether anything changed their mind. Move to a real choice only if a player offers one.', '[{"id": "f0", "type": "textarea", "label": "The decision we debated"}, {"id": "f1", "type": "textarea", "label": "The best argument for"}, {"id": "f2", "type": "textarea", "label": "The best argument against"}, {"id": "f3", "type": "textarea", "label": "What changed when I switched sides"}, {"id": "f4", "type": "textarea", "label": "A real choice I can look at this way"}]'::jsonb, array['group', 'play', 'decisions']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('values-auction-with-pretend-money', 'Values Auction with Pretend Money', 'game'::resource_kind, 'A pretend auction where players bid on values and find out what they care about most.', 'Use it to help players notice which values they would spend the most on.', array['Groups']::text[], '40 minutes', 'Give each player the same pretend budget and a list of values to bid on, such as family, learning, adventure and health. Run the auction, then ask what they chose and what they gave up. There are no right values. Close by asking how one of the won values could show up this week.', '[{"id": "f0", "type": "textarea", "label": "The value I spent the most on"}, {"id": "f1", "type": "textarea", "label": "A value I wished I could afford"}, {"id": "f2", "type": "textarea", "label": "What surprised me about my bids"}, {"id": "f3", "type": "textarea", "label": "How the value I won could show up this week"}, {"id": "f4", "type": "textarea", "label": "What I heard from others that I want to remember"}]'::jsonb, array['group', 'play', 'values']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('sound-hunt-listening-game', 'Sound Hunt Listening Game', 'game'::resource_kind, 'A game where players close their eyes and list every sound they can find.', 'Use it to help players practice listening and settling attention.', array['Groups']::text[], '20 minutes', 'Ask players to listen for one minute with eyes closed or lowered, counting sounds, then share the list. Try again with a different location. Debrief how attention felt and what it was like to come back when the mind wandered.', '[{"id": "f0", "type": "textarea", "label": "Sounds I heard close to me"}, {"id": "f1", "type": "textarea", "label": "Sounds I heard far away"}, {"id": "f2", "type": "textarea", "label": "The sound I liked most"}, {"id": "f3", "type": "textarea", "label": "What my mind did while I listened"}, {"id": "f4", "type": "textarea", "label": "Where I could listen this week"}]'::jsonb, array['group', 'play', 'mindfulness', 'attention']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('daily-rhythm-steadiness-planner', 'Daily Rhythm Steadiness Planner', 'worksheet'::resource_kind, 'A planner for placing rest, movement and contact through the day to keep a steady pace.', 'Use it to help a client build a predictable day that supports steadiness.', array['Adults']::text[], '25 minutes', 'Have the client sketch morning, afternoon and evening with one steadying item in each, such as a walk, a meal or a call, using only present-day routines. Note where the day tends to tip into overload or numbness. Keep the plan small and revisit it weekly.', '[{"id": "f0", "type": "textarea", "label": "My morning anchor"}, {"id": "f1", "type": "textarea", "label": "My afternoon anchor"}, {"id": "f2", "type": "textarea", "label": "My evening anchor"}, {"id": "f3", "type": "textarea", "label": "The part of the day that is hardest"}, {"id": "f4", "type": "textarea", "label": "What I will change this week"}]'::jsonb, array['PTSD and trauma', 'routines', 'stabilizing', 'sleep']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('reminder-response-plan-card', 'Reminder Response Plan Card', 'cbt'::resource_kind, 'A card for what a client does when a present-day reminder pulls their attention away.', 'Use it to help a client plan a calm response to everyday reminders.', array['Adults']::text[], '25 minutes', 'The client lists everyday reminders, such as a smell or a loud noise, without describing the events behind them. For each they write what they notice in the body, a thought to check and a steadying step. Practice one in session when calm and keep it brief.', '[{"id": "f0", "type": "textarea", "label": "A reminder that shows up in daily life, named briefly"}, {"id": "f1", "type": "textarea", "label": "What I notice in my body"}, {"id": "f2", "type": "textarea", "label": "A thought I can check against the present"}, {"id": "f3", "type": "textarea", "label": "A steadying step I can take"}, {"id": "f4", "type": "textarea", "label": "Who I could contact if it lingers"}]'::jsonb, array['PTSD and trauma', 'core CBT', 'triggers', 'stabilizing']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('anchoring-in-values-during-hard-memories', 'Anchoring in Values During Hard Memories', 'act'::resource_kind, 'A page that pairs an anchor in the present with a value the client is moving toward.', 'Use it to help a client stay connected to what matters when reminders show up.', array['Adults']::text[], '30 minutes', 'Start with the client''s values and present-day anchors, never with the content of memories. When a reminder shows up in daily life, they notice it, name it, feel their feet and take one small valued step. Pace carefully, and keep the work in the stabilizing range.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me"}, {"id": "f1", "type": "textarea", "label": "A reminder that sometimes shows up in daily life, named in a few words"}, {"id": "f2", "type": "textarea", "label": "A present-moment anchor I can use"}, {"id": "f3", "type": "textarea", "label": "One small step toward what matters"}, {"id": "f4", "type": "textarea", "label": "Who I can reach out to"}]'::jsonb, array['PTSD and trauma', 'core ACT', 'values', 'stabilizing']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('cool-down-sequence-after-a-hard-moment-card', 'Cool Down Sequence After a Hard Moment Card', 'dbt'::resource_kind, 'A card with a short sequence for settling the body and mind after a hard moment.', 'Use it to help a client settle after a reminder has set off strong reactions.', array['Adults']::text[], '20 minutes', 'Build a short sequence with the client: a cold drink, five slow breaths, naming five things they see, and a small next step. Practice in session when calm. The sequence is for settling after a moment passes and not for revisiting what happened.', '[{"id": "f0", "type": "textarea", "label": "The first thing I will do to settle"}, {"id": "f1", "type": "textarea", "label": "My breathing step"}, {"id": "f2", "type": "textarea", "label": "Five things I can see"}, {"id": "f3", "type": "textarea", "label": "My next small step"}, {"id": "f4", "type": "textarea", "label": "Who I could tell"}]'::jsonb, array['PTSD and trauma', 'core DBT', 'grounding', 'stabilizing']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('night-routine-and-sleep-partner-plan', 'Night Routine and Sleep Partner Plan', 'couples'::resource_kind, 'A plan for partners to make bedtime and nights feel safer and more restful.', 'Use it to help partners agree on a bedtime routine and what to do if nights are hard.', array['Couples']::text[], '35 minutes', 'Partners discuss what makes bedtime feel safe, such as light, door position or a wind-down, and what each does if one wakes up unsettled. Agree on a calm response and a way to go back to sleep. Neither partner is asked to share the content of any dream.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me feel safe at night"}, {"id": "f1", "type": "textarea", "label": "Partner B: what helps me feel safe at night"}, {"id": "f2", "type": "textarea", "label": "Our bedtime routine"}, {"id": "f3", "type": "textarea", "label": "What we do if one of us wakes unsettled"}, {"id": "f4", "type": "textarea", "label": "When we will review the plan"}]'::jsonb, array['PTSD and trauma', 'couples', 'sleep', 'safety']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('worry-volume-knob-cardboard-craft', 'Worry Volume Knob Cardboard Craft', 'kids'::resource_kind, 'A cardboard dial a child turns to show how loud a worry feels.', 'Use it to help a child show and adjust how big a worry feels.', array['Children']::text[], '30 minutes', 'The child decorates a dial from quiet to loud and turns it for a worry. Together try a breath or a silly voice for the worry and see whether the dial moves. The parent practices asking what number it is today, and does not argue the worry away. Keep it playful.', '[{"id": "f0", "type": "textarea", "label": "A worry I turned the dial for"}, {"id": "f1", "type": "textarea", "label": "The number it started at"}, {"id": "f2", "type": "textarea", "label": "What I did to turn it down"}, {"id": "f3", "type": "textarea", "label": "What my parent did that helped"}, {"id": "f4", "type": "textarea", "label": "What I will do when the dial is high"}]'::jsonb, array['anxiety', 'children', 'worry', 'play']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('uncertainty-dice-tolerance-game', 'Uncertainty Dice Tolerance Game', 'game'::resource_kind, 'A dice game where players try small uncertain choices and notice how they feel.', 'Use it to help players practice being unsure and finding they can cope.', array['Groups']::text[], '30 minutes', 'Each player rolls a die to pick a small uncertain task from a list, such as picking a snack blindly or choosing a seat without planning. Then they rate discomfort and what they did. Take turns, and let players pass once. Debrief what they noticed about unsureness rising and falling.', '[{"id": "f0", "type": "textarea", "label": "The small uncertain task I rolled"}, {"id": "f1", "type": "textarea", "label": "How uncomfortable I felt, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I did while I felt it"}, {"id": "f3", "type": "textarea", "label": "What happened in the end"}, {"id": "f4", "type": "textarea", "label": "An uncertain thing I could try this week"}]'::jsonb, array['anxiety', 'uncertainty', 'group', 'play']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('anxiety-day-and-night-pattern-calendar', 'Anxiety Day and Night Pattern Calendar', 'worksheet'::resource_kind, 'A calendar that tracks when anxiety is higher or lower across the week.', 'Use it to help a client see patterns by time of day and day of the week.', array['Adults']::text[], 'One week', 'The client rates anxiety morning, afternoon and evening on a weekly grid and notes what was happening. Look for peaks and quiet spots, and connect them to sleep, caffeine, plans and people. Plan one change for the highest-risk time.', '[{"id": "f0", "type": "textarea", "label": "The time of day anxiety is highest"}, {"id": "f1", "type": "textarea", "label": "What is going on at that time"}, {"id": "f2", "type": "textarea", "label": "The time it is lowest and what is happening"}, {"id": "f3", "type": "textarea", "label": "Patterns I see across the week"}, {"id": "f4", "type": "textarea", "label": "One change I will try"}]'::jsonb, array['anxiety', 'self-monitoring', 'pattern']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('best-worst-and-most-likely-outcome-sheet', 'Best, Worst and Most Likely Outcome Sheet', 'cbt'::resource_kind, 'A sheet for writing the best, worst and most likely outcomes of a worry.', 'Use it to help a client look at the whole range of outcomes, not just the worst.', array['Adults']::text[], '20 minutes', 'The client writes the worry, then the best case, the worst case and the most likely case, and how they would cope with each. Often the most likely case is ordinary. Ask what they would do about the worst case and which case they have been living in.', '[{"id": "f0", "type": "textarea", "label": "The worry"}, {"id": "f1", "type": "textarea", "label": "The best case"}, {"id": "f2", "type": "textarea", "label": "The worst case"}, {"id": "f3", "type": "textarea", "label": "The most likely case"}, {"id": "f4", "type": "textarea", "label": "How I would cope with each"}]'::jsonb, array['anxiety', 'core CBT', 'worry', 'uncertainty']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('making-room-for-anxiety-willingness-practice', 'Making Room for Anxiety Willingness Practice', 'act'::resource_kind, 'A practice page for letting anxiety be present while the client does what matters.', 'Use it to help a client carry anxiety along instead of waiting for it to leave first.', array['Adults']::text[], '25 minutes', 'Ask the client to choose a valued action that anxiety usually blocks, then to notice the feeling, give it room in the body and take the action anyway. Willingness is a choice, not a feeling. Review what happened without grading it, and talk about what they learned about the cost of waiting.', '[{"id": "f0", "type": "textarea", "label": "The valued action anxiety tends to block"}, {"id": "f1", "type": "textarea", "label": "What anxiety feels like in my body"}, {"id": "f2", "type": "textarea", "label": "How I made room for it"}, {"id": "f3", "type": "textarea", "label": "What I did next"}, {"id": "f4", "type": "textarea", "label": "What I learned about doing it with anxiety present"}]'::jsonb, array['anxiety', 'core ACT', 'willingness', 'values']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('pacing-energy-on-low-days-plan', 'Pacing Energy on Low Days Plan', 'dbt'::resource_kind, 'A plan for splitting a day''s tasks into small blocks with rests on low-energy days.', 'Use it to help a client do the essentials on low days without burning out.', array['Adults']::text[], '20 minutes', 'The client lists tasks, marks the essentials, and splits them into ten-minute blocks with a rest between. Wise mind decides what can wait. Invite them to track energy before and after. Review what helped and adjust.', '[{"id": "f0", "type": "textarea", "label": "The essentials for today"}, {"id": "f1", "type": "textarea", "label": "How I will split them into blocks"}, {"id": "f2", "type": "textarea", "label": "What I can let wait"}, {"id": "f3", "type": "textarea", "label": "How I will rest between blocks"}, {"id": "f4", "type": "textarea", "label": "My energy before and after"}]'::jsonb, array['depression', 'core DBT', 'pacing', 'wise mind']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('low-mood-days-partner-plan', 'Low-Mood Days Partner Plan', 'couples'::resource_kind, 'A plan for how partners stay connected on days when one has little energy.', 'Use it to give partners agreed ways to support each other on low-energy days.', array['Couples']::text[], '35 minutes', 'The partner with low mood lists what helps and what feels like pressure; the other shares what they can offer and what they need so they do not burn out. They agree on a few small supports and a check-in word. Frame it as a plan for the days, not a fix for the person.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps on a low day"}, {"id": "f1", "type": "textarea", "label": "Partner A: what feels like pressure"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can offer without burning out"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need for myself"}, {"id": "f4", "type": "textarea", "label": "Our check-in word and how we will use it"}]'::jsonb, array['depression', 'couples', 'support', 'communication']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('sunshine-and-cloud-feelings-journal-craft', 'Sunshine and Cloud Feelings Journal Craft', 'kids'::resource_kind, 'A small journal where a child draws a sun or cloud for each day and one reason why.', 'Use it to help a child notice how days feel and what changes them.', array['Children']::text[], '30 minutes', 'The child decorates a journal and draws a sun, cloud or both each evening with one reason. The parent looks at it with them, listens and notices activities linked to sunny days. Look together for patterns in session. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "How I decorated my journal"}, {"id": "f1", "type": "textarea", "label": "A sunny day and why"}, {"id": "f2", "type": "textarea", "label": "A cloudy day and why"}, {"id": "f3", "type": "textarea", "label": "Something that helps clouds move"}, {"id": "f4", "type": "textarea", "label": "Who I share my journal with"}]'::jsonb, array['depression', 'children', 'emotion identification', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('activity-menu-spin-and-try-game', 'Activity Menu Spin and Try Game', 'game'::resource_kind, 'A spin-the-wheel game that picks a small activity for a client to try.', 'Use it to help a group choose and try small activities that lift mood.', array['Groups']::text[], '30 minutes', 'Build a wheel of simple activities the group names, such as stretching, texting a friend or stepping outside. Players spin, try or plan the activity, and report how it felt. Let players re-spin once. Debrief which activities were doable and what made starting easier.', '[{"id": "f0", "type": "textarea", "label": "The activity I spun"}, {"id": "f1", "type": "textarea", "label": "When I will try it"}, {"id": "f2", "type": "textarea", "label": "How I felt after, if I tried it"}, {"id": "f3", "type": "textarea", "label": "What made starting easier or harder"}, {"id": "f4", "type": "textarea", "label": "A new activity to add to the wheel"}]'::jsonb, array['depression', 'behavioral activation', 'group', 'play']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('low-day-and-better-day-comparison-sheet', 'Low Day and Better Day Comparison Sheet', 'worksheet'::resource_kind, 'A two-column sheet that compares what a low day and a better day looked like.', 'Use it to help a client spot what changes between low days and better days.', array['Adults']::text[], '20 minutes', 'Have the client describe a recent low day and a recent better day in the same categories: sleep, contact with people, movement, and what they did. Look at what differed and which difference they could influence. If thoughts of ending their life show up, complete the 988 prompt in session; 988 can be called or texted.', '[{"id": "f0", "type": "textarea", "label": "A low day: what I did and who I saw"}, {"id": "f1", "type": "textarea", "label": "A better day: what I did and who I saw"}, {"id": "f2", "type": "textarea", "label": "What was different between them"}, {"id": "f3", "type": "textarea", "label": "One difference I could influence"}, {"id": "f4", "type": "textarea", "label": "If thoughts of ending my life show up, I can call or text 988"}]'::jsonb, array['depression', 'self-monitoring', 'pattern']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('task-chunking-estimate-ladder', 'Task Chunking Estimate Ladder', 'cbt'::resource_kind, 'A ladder that breaks a big task into rungs and estimates each one.', 'Use it to help a client see a big task as a series of short, doable pieces.', array['Adults']::text[], '25 minutes', 'The client writes a big task, breaks it into rungs of about fifteen minutes and estimates each. They try a rung and compare. Adjust estimates over time. Celebrate each rung completed and pick the first rung to start today.', '[{"id": "f0", "type": "textarea", "label": "The big task"}, {"id": "f1", "type": "textarea", "label": "The rungs on my ladder"}, {"id": "f2", "type": "textarea", "label": "My estimate for each rung"}, {"id": "f3", "type": "textarea", "label": "How long the first rung really took"}, {"id": "f4", "type": "textarea", "label": "The rung I will do next"}]'::jsonb, array['ADHD', 'core CBT', 'executive function', 'planning']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('starting-before-ready-valued-action-page', 'Starting Before Ready Valued Action Page', 'act'::resource_kind, 'A page for taking the first small step on a task even when motivation is missing.', 'Use it to help a client start a valued task with the feelings of dread or boredom along.', array['Adults']::text[], '25 minutes', 'Name the task, the value behind it, and the feeling that blocks starting. The client picks a two-minute first step and a cue. Remind them that the feeling can come along. Review whether starting happened, and shrink the step if it did not.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "The value behind it"}, {"id": "f2", "type": "textarea", "label": "The feeling that gets in the way"}, {"id": "f3", "type": "textarea", "label": "A two-minute first step"}, {"id": "f4", "type": "textarea", "label": "The cue that will tell me to start"}]'::jsonb, array['ADHD', 'core ACT', 'task initiation', 'values']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('task-switching-urge-surfing-card', 'Task-Switching Urge Surfing Card', 'dbt'::resource_kind, 'A card for noticing the urge to switch tasks and riding it out for a few minutes.', 'Use it to help a client stay with a task a little longer than the urge suggests.', array['Adults']::text[], '20 minutes', 'Name the urge to switch, set a short timer, and have the client breathe and note the urge rising and falling before deciding. Write the distraction on a list for later. Start with five minutes and extend only if it works.', '[{"id": "f0", "type": "textarea", "label": "The task I want to stay with"}, {"id": "f1", "type": "textarea", "label": "The urge to switch, in a few words"}, {"id": "f2", "type": "textarea", "label": "What I noticed while the timer ran"}, {"id": "f3", "type": "textarea", "label": "What I wrote on my later list"}, {"id": "f4", "type": "textarea", "label": "How long I will try next time"}]'::jsonb, array['ADHD', 'core DBT', 'mindfulness', 'attention']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('shared-household-systems-planner', 'Shared Household Systems Planner', 'couples'::resource_kind, 'A planner where partners set up visible routines for the tasks that slip.', 'Use it to help partners set up systems so reminders do not turn into nagging.', array['Couples']::text[], '40 minutes', 'List recurring household tasks, who does each, and the system that makes each one visible, such as a shared calendar or a labeled basket. Agree how a reminder is asked for and given, so nobody has to be the nag. Test the system for two weeks and revisit it.', '[{"id": "f0", "type": "textarea", "label": "Tasks that tend to slip"}, {"id": "f1", "type": "textarea", "label": "Who does each one now"}, {"id": "f2", "type": "textarea", "label": "A visible system for each, such as a list or alarm"}, {"id": "f3", "type": "textarea", "label": "How we ask for and give a reminder kindly"}, {"id": "f4", "type": "textarea", "label": "When we will review the system"}]'::jsonb, array['ADHD', 'couples', 'routines', 'communication']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('focus-racetrack-game-board', 'Focus Racetrack Game Board', 'kids'::resource_kind, 'A board a child makes that turns task steps into laps around a track.', 'Use it to help a child break a task into steps and see progress as they go.', array['Children']::text[], '30 minutes', 'Draw a racetrack with spaces labeled by steps, such as get backpack or write a sentence. The child moves a token one space per step with a small break after each lap. Explain to the parent that the track is a tool for the task, not a reward for behavior. Adjust step size so success is likely.', '[{"id": "f0", "type": "textarea", "label": "A task I will use the track for"}, {"id": "f1", "type": "textarea", "label": "The steps on my track"}, {"id": "f2", "type": "textarea", "label": "The step that is hardest to start"}, {"id": "f3", "type": "textarea", "label": "What I do on my break"}, {"id": "f4", "type": "textarea", "label": "Who helps me with the track"}]'::jsonb, array['ADHD', 'children', 'executive function', 'play']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('urge-surfing-wave-game', 'Urge Surfing Wave Game', 'game'::resource_kind, 'A game where players ride out an urge as a wave using breath and movement.', 'Use it to help players practice staying with an urge as it rises and falls.', array['Groups']::text[], '25 minutes', 'Players imagine an urge as a wave and move a hand up and down in time with their breath, rating the urge as it passes. Take turns describing what they noticed. The point is that urges rise and fall, not that they must be defeated. Debrief where players could use this and who they could call.', '[{"id": "f0", "type": "textarea", "label": "The urge I pictured as a wave"}, {"id": "f1", "type": "textarea", "label": "How strong it got, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I noticed as it passed"}, {"id": "f3", "type": "textarea", "label": "What helped me ride it"}, {"id": "f4", "type": "textarea", "label": "Where I could use this skill"}]'::jsonb, array['addiction', 'urges', 'group', 'mindfulness']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('free-time-gap-filler-weekly-schedule', 'Free Time Gap Filler Weekly Schedule', 'worksheet'::resource_kind, 'A schedule that plans activities for the hours when urges are most likely.', 'Use it to help a client fill high-risk hours with things that matter to them.', array['Adults']::text[], '30 minutes', 'The client marks the hours of the week when substance use urges tend to rise and chooses an activity or person for each. Include one rewarding thing per day. Review which hours were still hard and adjust the plan.', '[{"id": "f0", "type": "textarea", "label": "The hours when urges are highest"}, {"id": "f1", "type": "textarea", "label": "What I will do in those hours"}, {"id": "f2", "type": "textarea", "label": "Who I will contact"}, {"id": "f3", "type": "textarea", "label": "One rewarding thing each day"}, {"id": "f4", "type": "textarea", "label": "What I will change if the plan is not working"}]'::jsonb, array['addiction', 'planning', 'routines', 'substance use']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('urge-thoughts-alternatives-sheet', 'Urge Thoughts Alternatives Sheet', 'cbt'::resource_kind, 'A sheet for catching thoughts that push toward substance use and trying other responses.', 'Use it to help a client notice urge-related thoughts and choose a response.', array['Adults']::text[], '25 minutes', 'The client writes the thought that comes with an urge, such as one won''t hurt, then what is true on the other side, such as the last time one led to more. Next, they write a response they can use. Bring a recent example and try it aloud.', '[{"id": "f0", "type": "textarea", "label": "The thought that came with the urge"}, {"id": "f1", "type": "textarea", "label": "What happens when I follow it, in my own experience"}, {"id": "f2", "type": "textarea", "label": "A different thing I can tell myself"}, {"id": "f3", "type": "textarea", "label": "What I will do instead"}, {"id": "f4", "type": "textarea", "label": "Who I can tell about it"}]'::jsonb, array['addiction', 'core CBT', 'urges', 'substance use']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('urges-and-values-compass-practice', 'Urges and Values Compass Practice', 'act'::resource_kind, 'A page that sets an urge beside the value a client wants to live by.', 'Use it to help a client make room for an urge while choosing the direction of their life.', array['Adults']::text[], '30 minutes', 'Ask the client what matters most, what the urge asks for, and what each path costs and gives. Practice noticing the urge in the body, giving it room, and taking one step toward the value. Keep it non-judgmental and use the client''s own words for substance use.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me"}, {"id": "f1", "type": "textarea", "label": "What the urge asks me to do"}, {"id": "f2", "type": "textarea", "label": "What following it costs me"}, {"id": "f3", "type": "textarea", "label": "One step toward what matters"}, {"id": "f4", "type": "textarea", "label": "How I make room for the urge in my body"}]'::jsonb, array['addiction', 'core ACT', 'urges', 'values']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('urge-survival-distraction-menu', 'Urge Survival Distraction Menu', 'dbt'::resource_kind, 'A menu of distractions a client can reach for when an urge is strong.', 'Use it to help a client get through the peak of an urge without acting on it.', array['Adults']::text[], '20 minutes', 'Build the menu with the client: activities that fully occupy attention, such as cold water, a call, a brisk walk or a puzzle. Include people to contact and a place to go. Practice one in session. Encourage the client to keep it where they will see it in a hard moment.', '[{"id": "f0", "type": "textarea", "label": "Activities that take my full attention"}, {"id": "f1", "type": "textarea", "label": "People I can call or text"}, {"id": "f2", "type": "textarea", "label": "A place I can go that helps"}, {"id": "f3", "type": "textarea", "label": "What I will tell myself when the urge peaks"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this menu"}]'::jsonb, array['addiction', 'core DBT', 'distress tolerance', 'urges']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('anger-cooling-off-agreement', 'Anger Cooling-Off Agreement', 'couples'::resource_kind, 'An agreement partners write for pausing and returning to a heated conversation.', 'Use it to help partners agree on how to pause a heated moment and come back.', array['Couples']::text[], '30 minutes', 'Partners agree on a signal, a length of break, where each will go and what they will do to cool down, plus a time to come back. The break is not an exit; whoever calls it returns. Practice the signal in session and review how it went after the first use.', '[{"id": "f0", "type": "textarea", "label": "Our signal to pause"}, {"id": "f1", "type": "textarea", "label": "How long we take, and where we each go"}, {"id": "f2", "type": "textarea", "label": "What I will do to cool down"}, {"id": "f3", "type": "textarea", "label": "When and how we come back"}, {"id": "f4", "type": "textarea", "label": "What we will do if one of us does not come back on time"}]'::jsonb, array['anger management', 'couples', 'de-escalation', 'communication']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('anger-volcano-signs-model-craft', 'Anger Volcano Signs Model Craft', 'kids'::resource_kind, 'A volcano a child builds and labels with early signs, the eruption and calming steps.', 'Use it to help a child spot early anger signs and choose a calming step.', array['Children']::text[], '35 minutes', 'The child builds a volcano from paper and labels the lower slopes with early signs such as hot face or clenched fists, and the top with what comes out. Add calming steps at the base. The parent learns the early signs and offers the child a calming choice, not a lecture, when they see one.', '[{"id": "f0", "type": "textarea", "label": "Early signs I notice in my body"}, {"id": "f1", "type": "textarea", "label": "What comes out when it erupts"}, {"id": "f2", "type": "textarea", "label": "A calming step I like"}, {"id": "f3", "type": "textarea", "label": "What my parent can say or do"}, {"id": "f4", "type": "textarea", "label": "A time I used a calming step"}]'::jsonb, array['anger management', 'children', 'de-escalation', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('anger-thermometer-charades', 'Anger Thermometer Charades', 'game'::resource_kind, 'A charades game where players act out different anger levels and calming steps.', 'Use it to help players practice noticing anger levels and the steps that cool them.', array['Groups']::text[], '25 minutes', 'Players draw cards naming a level on a zero to ten scale and act out what it looks like in the body and voice, then a calming step. Others guess the level. Rotate turns and let players pass. Debrief which levels are easiest to catch and which steps they would use.', '[{"id": "f0", "type": "textarea", "label": "The level I acted out"}, {"id": "f1", "type": "textarea", "label": "What anger looks like in my body at that level"}, {"id": "f2", "type": "textarea", "label": "A calming step I acted out"}, {"id": "f3", "type": "textarea", "label": "A level where I most want to catch it"}, {"id": "f4", "type": "textarea", "label": "What I learned about early signs"}]'::jsonb, array['anger management', 'group', 'play', 'regulation']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('anger-trigger-and-underlying-feeling-log', 'Anger Trigger and Underlying Feeling Log', 'worksheet'::resource_kind, 'A log that traces an angry moment back to the feeling underneath it.', 'Use it to help a client see what sits under anger, such as hurt or worry.', array['Adults']::text[], '20 minutes', 'The client logs the trigger, body signs, thought, what they did and the softer feeling under the anger, if any. Over a week they look for patterns. Do not argue with the anger; validate it first and then explore what it protects. Choose one pattern to practice a different response.', '[{"id": "f0", "type": "textarea", "label": "The trigger"}, {"id": "f1", "type": "textarea", "label": "Where I felt anger in my body"}, {"id": "f2", "type": "textarea", "label": "The thought that went with it"}, {"id": "f3", "type": "textarea", "label": "The feeling underneath the anger"}, {"id": "f4", "type": "textarea", "label": "What I did and what I would try next time"}]'::jsonb, array['anger management', 'triggers', 'self-monitoring', 'emotion identification']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('anger-rules-and-expectations-rewrite', 'Anger Rules and Expectations Rewrite', 'cbt'::resource_kind, 'A sheet that finds unspoken rules behind anger and rewrites them as requests.', 'Use it to help a client turn unspoken rules into specific, fair requests.', array['Adults']::text[], '25 minutes', 'The client writes the rule that was broken, such as people should always be on time, whether the other person knew it and a rewrite as a request. Ask what they can control. Role-play making the request calmly.', '[{"id": "f0", "type": "textarea", "label": "The rule I felt was broken"}, {"id": "f1", "type": "textarea", "label": "Whether the other person knew my rule"}, {"id": "f2", "type": "textarea", "label": "How the rule might be a request"}, {"id": "f3", "type": "textarea", "label": "What I can control"}, {"id": "f4", "type": "textarea", "label": "How I will make the request"}]'::jsonb, array['anger management', 'core CBT', 'belief change', 'fairness']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('unwanted-thoughts-passing-clouds-practice', 'Unwanted Thoughts Passing Clouds Practice', 'act'::resource_kind, 'A practice page for watching intrusive thoughts drift by like clouds.', 'Use it to help a client notice intrusive thoughts without wrestling with them.', array['Adults']::text[], '25 minutes', 'Guide the client to picture the sky and let each unwanted thought drift in and out as a cloud, noting but not chasing it. Ask what pulled them into a thought and what they did next. The aim is a different relationship to the thought, not getting rid of it; avoid reassurance in session.', '[{"id": "f0", "type": "textarea", "label": "An unwanted thought that shows up"}, {"id": "f1", "type": "textarea", "label": "What I usually do when it shows up"}, {"id": "f2", "type": "textarea", "label": "What it was like to watch it pass"}, {"id": "f3", "type": "textarea", "label": "What pulled me in"}, {"id": "f4", "type": "textarea", "label": "What I would rather be doing with my time"}]'::jsonb, array['OCD', 'core ACT', 'defusion', 'mindfulness']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-not-knowing-card', 'Radical Acceptance of Not Knowing Card', 'dbt'::resource_kind, 'A card for accepting that some uncertainty cannot be resolved and acting anyway.', 'Use it to help a client practice accepting uncertainty in small steps.', array['Adults']::text[], '20 minutes', 'The client writes an uncertainty they struggle with and the sentence it is what it is and I cannot know right now. Practice breathing and half-smile with it, and choose a small valued act. Acceptance is not liking it.', '[{"id": "f0", "type": "textarea", "label": "An uncertainty I struggle with"}, {"id": "f1", "type": "textarea", "label": "My acceptance sentence"}, {"id": "f2", "type": "textarea", "label": "What I notice in my body when I say it"}, {"id": "f3", "type": "textarea", "label": "A small valued action I can take"}, {"id": "f4", "type": "textarea", "label": "What I will do when doubt returns"}]'::jsonb, array['OCD', 'core DBT', 'radical acceptance', 'uncertainty']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('family-accommodation-gentle-reduction-plan', 'Family Accommodation Gentle Reduction Plan', 'couples'::resource_kind, 'A plan for partners to slowly change the ways they adapt around rituals.', 'Use it to help partners agree on small reductions in accommodating rituals.', array['Couples']::text[], '35 minutes', 'List the ways the partner adapts, such as waiting, checking or avoiding, and rank them. Choose one to reduce a little at a time, agree on what to say, and plan how to support each other. Do it at the pace of the person with the rituals and review weekly.', '[{"id": "f0", "type": "textarea", "label": "Partner A: ways my partner adapts to my rituals"}, {"id": "f1", "type": "textarea", "label": "Partner B: ways I adapt"}, {"id": "f2", "type": "textarea", "label": "The first one we will reduce"}, {"id": "f3", "type": "textarea", "label": "What I will say instead"}, {"id": "f4", "type": "textarea", "label": "How we will check in"}]'::jsonb, array['OCD', 'couples', 'boundaries', 'support']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('bossy-brain-name-and-draw-activity', 'Bossy Brain Name and Draw Activity', 'kids'::resource_kind, 'A drawing activity where a child names and draws the bossy voice that insists on rituals.', 'Use it to help a child see the bossy thought as separate from themselves.', array['Children']::text[], '30 minutes', 'The child draws and names the bossy voice, and what it tells them to do. Together make a plan for answering it, such as I hear you but not now. The parent practices staying calm and not joining in rituals, with your guidance. Keep it playful, and externalize the voice, not the child.', '[{"id": "f0", "type": "textarea", "label": "The name and picture of my bossy brain"}, {"id": "f1", "type": "textarea", "label": "What it tells me to do"}, {"id": "f2", "type": "textarea", "label": "What I say back to it"}, {"id": "f3", "type": "textarea", "label": "What my parent says and does"}, {"id": "f4", "type": "textarea", "label": "A brave thing I did this week"}]'::jsonb, array['OCD', 'children', 'externalizing', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('doubt-tolerance-maybe-game', 'Doubt Tolerance Maybe Game', 'game'::resource_kind, 'A game where players answer with maybe and sit with not knowing.', 'Use it to help players practice tolerating doubt without seeking certainty.', array['Groups']::text[], '25 minutes', 'Read out small uncertain scenarios and have players answer with maybe, I do not know, or we will see, then rate how it felt. Take turns, and let players pass. Debrief what made not knowing easier or harder, and where they could practice it this week.', '[{"id": "f0", "type": "textarea", "label": "A scenario that felt uncomfortable"}, {"id": "f1", "type": "textarea", "label": "How strong the discomfort was, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I said instead of seeking certainty"}, {"id": "f3", "type": "textarea", "label": "What happened to the discomfort"}, {"id": "f4", "type": "textarea", "label": "A doubt I could practice with this week"}]'::jsonb, array['OCD', 'uncertainty', 'group', 'play']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('after-the-surge-recovery-plan', 'After-the-Surge Recovery Plan', 'worksheet'::resource_kind, 'A plan for what a client does in the hour after a surge of panic to settle.', 'Use it to help a client recover after panic and return to their day.', array['Adults']::text[], '20 minutes', 'The client plans for the hour after: a drink, a slow walk, a note of what happened and the next step in the day. Include what to tell themselves about the surge having passed. Practice in session and refine after the next time.', '[{"id": "f0", "type": "textarea", "label": "What I need right after a surge"}, {"id": "f1", "type": "textarea", "label": "What I will say to myself"}, {"id": "f2", "type": "textarea", "label": "The next thing I will do in my day"}, {"id": "f3", "type": "textarea", "label": "Who I might tell"}, {"id": "f4", "type": "textarea", "label": "What I will write down"}]'::jsonb, array['panic attacks', 'coping skills', 'planning']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('body-sensation-misreading-check-sheet', 'Body Sensation Misreading Check Sheet', 'cbt'::resource_kind, 'A sheet for catching the scary meaning given to a body sensation and testing other readings.', 'Use it to help a client consider other explanations for the sensations of panic.', array['Adults']::text[], '25 minutes', 'The client writes the sensation, the scary meaning, and other possible explanations such as exertion, caffeine or fast breathing. Look at what happened the last several times the fear came true. Share that sensations are uncomfortable but not dangerous in themselves; confirm medical questions with their doctor.', '[{"id": "f0", "type": "textarea", "label": "The body sensation I noticed"}, {"id": "f1", "type": "textarea", "label": "The scary meaning I gave it"}, {"id": "f2", "type": "textarea", "label": "Other possible explanations"}, {"id": "f3", "type": "textarea", "label": "What happened the last times I feared this"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself next time"}]'::jsonb, array['panic attacks', 'core CBT', 'thinking traps', 'body awareness']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('opening-up-to-panic-willingness-page', 'Opening Up to Panic Willingness Page', 'act'::resource_kind, 'A page for dropping the struggle against panic sensations and acting on values.', 'Use it to help a client let panic come and go while moving toward what matters.', array['Adults']::text[], '25 minutes', 'Ask what the client has been avoiding because of panic and what it costs. Practice noticing sensations, naming them and letting them be while doing a valued action. Be clear that willingness is not liking the feeling. Debrief any difference between fighting and allowing.', '[{"id": "f0", "type": "textarea", "label": "Something panic has kept me from"}, {"id": "f1", "type": "textarea", "label": "What avoiding it has cost me"}, {"id": "f2", "type": "textarea", "label": "What the sensations were like when I let them be"}, {"id": "f3", "type": "textarea", "label": "The valued action I took anyway"}, {"id": "f4", "type": "textarea", "label": "What I noticed about fighting versus allowing"}]'::jsonb, array['panic attacks', 'core ACT', 'willingness', 'values']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('slow-exhale-and-cold-cheeks-skill-card', 'Slow Exhale and Cold Cheeks Skill Card', 'dbt'::resource_kind, 'A card combining slow exhale breathing and cold water for strong body arousal.', 'Use it to help a client lower body arousal with two simple, portable skills.', array['Adults']::text[], '20 minutes', 'Teach breathing with a longer exhale than inhale and the cold-water step of holding a cold pack to the cheeks, and have the client try each in session. Check medical considerations for cold water. Explain that the skills help the body settle; they are not a way to stop the feeling at all costs.', '[{"id": "f0", "type": "textarea", "label": "How I did the paced breathing"}, {"id": "f1", "type": "textarea", "label": "How I used cold water"}, {"id": "f2", "type": "textarea", "label": "What changed in my body"}, {"id": "f3", "type": "textarea", "label": "Where I will practice them"}, {"id": "f4", "type": "textarea", "label": "What I will remember to try first"}]'::jsonb, array['panic attacks', 'core DBT', 'distress tolerance', 'breathing']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('panic-moment-partner-coaching-script', 'Panic Moment Partner Coaching Script', 'couples'::resource_kind, 'A script that tells a partner what to say and do when panic shows up.', 'Use it to help a partner be calm and useful in the middle of a panic surge.', array['Couples']::text[], '30 minutes', 'The person who panics writes what they want to hear and do, such as stay with me and remind me to breathe out. The partner writes how they will stay calm. Rehearse the script once in session. Remind both that the aim is to be a steady presence, not to take the panic away.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I want my partner to say"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I do not want my partner to do"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I will stay steady"}, {"id": "f3", "type": "textarea", "label": "Our short phrase for the moment"}, {"id": "f4", "type": "textarea", "label": "What we will do afterward"}]'::jsonb, array['panic attacks', 'couples', 'support', 'communication']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('evening-family-feelings-sticker-chart', 'Evening Family Feelings Sticker Chart', 'kids'::resource_kind, 'A family chart where each member sticks a feelings marker each evening.', 'Use it to help a family share how everyone feels without long talks.', array['Children']::text[], '30 minutes', 'The child decorates a chart with a column for each family member and stickers for feelings. Each evening everyone places a sticker and the parent offers one sentence of listening. Parents are asked to model feelings too. Keep it brief and go back to the chart in session.', '[{"id": "f0", "type": "textarea", "label": "How my family uses the chart"}, {"id": "f1", "type": "textarea", "label": "A feeling I put on the chart this week"}, {"id": "f2", "type": "textarea", "label": "A feeling someone else put on the chart"}, {"id": "f3", "type": "textarea", "label": "What my parent did when I shared"}, {"id": "f4", "type": "textarea", "label": "What I would like to add to the chart"}]'::jsonb, array['parenting', 'children', 'emotion identification', 'family']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('calm-voice-whisper-challenge-game', 'Calm Voice Whisper Challenge Game', 'game'::resource_kind, 'A game where parents practice lowering their voice to give a request.', 'Use it to help parents practice calm tone and short requests.', array['Groups']::text[], '30 minutes', 'Pairs act out a short household scene, and the parent gives the request in a whisper, then at a normal voice. Notice how the child role responds. Rotate roles. Debrief what it was like to slow down and what the parent can try at home.', '[{"id": "f0", "type": "textarea", "label": "The scene we acted"}, {"id": "f1", "type": "textarea", "label": "How I gave the request"}, {"id": "f2", "type": "textarea", "label": "How it felt as the child"}, {"id": "f3", "type": "textarea", "label": "What changed with a lower voice"}, {"id": "f4", "type": "textarea", "label": "What I will try at home"}]'::jsonb, array['parenting', 'group', 'play', 'de-escalation']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('parent-routine-anchors-planner', 'Parent Routine Anchors Planner', 'worksheet'::resource_kind, 'A planner for choosing a few predictable anchors in the family''s day.', 'Use it to help parents build a few predictable moments that make days smoother.', array['Adults']::text[], '25 minutes', 'Have the parent list the hard parts of the day and choose two or three anchors, such as a morning checklist or a bedtime order. Choose ones the whole household can keep. Start with one, review in a week and adjust. Routines work better when the child helps create them.', '[{"id": "f0", "type": "textarea", "label": "The hardest parts of our day"}, {"id": "f1", "type": "textarea", "label": "Two or three anchors I will try"}, {"id": "f2", "type": "textarea", "label": "How my child will help build them"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "When I will review how it is going"}]'::jsonb, array['parenting', 'routines', 'planning']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('parent-thoughts-and-reactions-record', 'Parent Thoughts and Reactions Record', 'cbt'::resource_kind, 'A record linking a parent''s thought in a hard moment to what they did next.', 'Use it to help a parent notice thoughts that fuel reactions and choose a response.', array['Adults']::text[], '25 minutes', 'The parent describes a recent hard moment, the thought that came up, such as he is doing this on purpose, the feeling, and what they did. Then they write another reading and what they would like to do. Be warm and avoid blame; most parents are doing their best under stress.', '[{"id": "f0", "type": "textarea", "label": "The moment with my child"}, {"id": "f1", "type": "textarea", "label": "The thought that came up"}, {"id": "f2", "type": "textarea", "label": "The feeling and what I did"}, {"id": "f3", "type": "textarea", "label": "Another way to read what happened"}, {"id": "f4", "type": "textarea", "label": "What I want to do next time"}]'::jsonb, array['parenting', 'core CBT', 'automatic thoughts']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('parenting-on-autopilot-noticing-page', 'Parenting on Autopilot Noticing Page', 'act'::resource_kind, 'A page for noticing moments of parenting on autopilot and choosing a values-based response.', 'Use it to help a parent catch autopilot reactions and choose a response.', array['Adults']::text[], '25 minutes', 'The parent describes a common moment in which they react automatically, the thought and feeling, and what they would like to do instead. Practice a pause and a values-based line. Keep it kind and brief and try one moment this week.', '[{"id": "f0", "type": "textarea", "label": "A moment I react on autopilot"}, {"id": "f1", "type": "textarea", "label": "The thought and feeling that come with it"}, {"id": "f2", "type": "textarea", "label": "What I want to do instead"}, {"id": "f3", "type": "textarea", "label": "The pause I will use"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I tried"}]'::jsonb, array['parenting', 'core ACT', 'values', 'mindfulness']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('postpartum-self-care-basics-checklist', 'Postpartum Self-Care Basics Checklist', 'dbt'::resource_kind, 'A short checklist of basic needs a new parent can protect, such as sleep, food, and contact.', 'Use it to help a new parent protect the basics when everything is demanding.', array['Adults']::text[], '20 minutes', 'List the basics, such as rest when possible, water, a meal, a bit of fresh air and a call to someone, and have the parent choose what is realistic this week. Include who can step in. Do not set high targets; the aim is one small thing each day, and to ask for help.', '[{"id": "f0", "type": "textarea", "label": "The basics I am managing"}, {"id": "f1", "type": "textarea", "label": "The ones that slip"}, {"id": "f2", "type": "textarea", "label": "One I will protect this week"}, {"id": "f3", "type": "textarea", "label": "Who can take over the baby while I do it"}, {"id": "f4", "type": "textarea", "label": "What I will say to ask for help"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'self-soothing', 'support']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('new-baby-division-of-labor-talk', 'New Baby Division of Labor Talk', 'couples'::resource_kind, 'A conversation guide for talking about who does what and who rests in the first months.', 'Use it to help partners plan nights, tasks and rest in a way they both can live with.', array['Couples']::text[], '40 minutes', 'Each partner lists the tasks they see, then they share the lists and notice what they had not seen. Plan nights and days with rest for both and a way to adjust when needs change. Give each partner a turn to say what they need, and look for small shifts that are fair to both.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I see that need doing"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I see that need doing"}, {"id": "f2", "type": "textarea", "label": "How we will split nights and rest"}, {"id": "f3", "type": "textarea", "label": "What each of us needs this week"}, {"id": "f4", "type": "textarea", "label": "When we will adjust the plan together"}]'::jsonb, array['perinatal and postpartum', 'couples', 'communication', 'planning']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('baby-care-pretend-play-session', 'Baby Care Pretend Play Session', 'kids'::resource_kind, 'A play session where a child practices gentle baby care with a doll.', 'Use it to help a child get ready to be gentle and involved with a new baby.', array['Children']::text[], '30 minutes', 'The child cares for a doll: holding, feeding with a bottle, singing. The parent shows gentle touch and praises it. Talk about what babies need and what the child will still do just with the parent. Accept any feelings that come up.', '[{"id": "f0", "type": "textarea", "label": "How I took care of the doll"}, {"id": "f1", "type": "textarea", "label": "What the baby will need"}, {"id": "f2", "type": "textarea", "label": "What I will do with the baby"}, {"id": "f3", "type": "textarea", "label": "What I will still do with my parent"}, {"id": "f4", "type": "textarea", "label": "How I feel about the baby coming"}]'::jsonb, array['perinatal and postpartum', 'children', 'play', 'family']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('tiny-joys-and-hard-moments-sorting-game', 'Tiny Joys and Hard Moments Sorting Game', 'game'::resource_kind, 'A sorting game where new parents place moments on a joy or hard pile and share.', 'Use it to help new parents see that joy and strain sit side by side.', array['Groups']::text[], '30 minutes', 'Write moments on cards and have players place them on pile or both. Then each shares one from each pile if they like. Others listen without fixing. Debrief what it was like to see that both belong.', '[{"id": "f0", "type": "textarea", "label": "A tiny joy from this week"}, {"id": "f1", "type": "textarea", "label": "A hard moment from this week"}, {"id": "f2", "type": "textarea", "label": "One I put in both piles"}, {"id": "f3", "type": "textarea", "label": "What I heard from others"}, {"id": "f4", "type": "textarea", "label": "Something I will take home"}]'::jsonb, array['perinatal and postpartum', 'group', 'play', 'connection']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('mood-and-sleep-notes-for-new-parents', 'Mood and Sleep Notes for New Parents', 'worksheet'::resource_kind, 'A log for noting mood, sleep and support to share with a clinician or doctor.', 'Use it to give a new parent and clinician a clearer picture of how the days go.', array['Adults']::text[], 'One week', 'The parent jots down hours of sleep, mood, a good moment and how much help they had. Review for patterns and how they feel. If the parent describes feeling overwhelmed or unsafe, follow your own clinical judgment and local guidance; 988 can be called or texted any time.', '[{"id": "f0", "type": "textarea", "label": "Hours I slept and how rested I felt"}, {"id": "f1", "type": "textarea", "label": "My mood today in a few words"}, {"id": "f2", "type": "textarea", "label": "A good moment today"}, {"id": "f3", "type": "textarea", "label": "The help I had today"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'self-monitoring', 'sleep', 'support']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('strengths-evidence-record', 'Strengths Evidence Record', 'cbt'::resource_kind, 'A record where a client collects concrete evidence for a strength they doubt.', 'Use it to help a client back a positive belief about themselves with real examples.', array['Adults']::text[], 'One week', 'Choose a strength the client doubts, such as I can handle hard things, and have them log concrete examples each day. Review for patterns and have them rate belief in the strength before and after. Keep the examples specific and observable.', '[{"id": "f0", "type": "textarea", "label": "The strength I want to find evidence for"}, {"id": "f1", "type": "textarea", "label": "Today''s example"}, {"id": "f2", "type": "textarea", "label": "What it says about me"}, {"id": "f3", "type": "textarea", "label": "How much I believe it, 0 to 100"}, {"id": "f4", "type": "textarea", "label": "What I will look for tomorrow"}]'::jsonb, array['self-esteem', 'core CBT', 'evidence log', 'strengths']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('self-worth-beyond-roles-reflection', 'Self-Worth Beyond Roles Reflection', 'act'::resource_kind, 'A reflection that separates who a client is from the roles and results they hold.', 'Use it to help a client see worth that does not depend on performance.', array['Adults']::text[], '30 minutes', 'Ask the client to list roles and results they use to judge themselves, and then what is left when they set them aside. Use the self-as-context idea: the observer who notices. Ask for a time they were kind to someone regardless of performance, and apply that to themselves.', '[{"id": "f0", "type": "textarea", "label": "Roles and results I use to judge myself"}, {"id": "f1", "type": "textarea", "label": "What I notice when I set them aside"}, {"id": "f2", "type": "textarea", "label": "A person I accept no matter what they achieve"}, {"id": "f3", "type": "textarea", "label": "What I would say to myself the same way"}, {"id": "f4", "type": "textarea", "label": "One action that reflects my own values"}]'::jsonb, array['self-esteem', 'core ACT', 'self-as-context', 'values']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('wise-mind-self-worth-statement-builder', 'Wise Mind Self-Worth Statement Builder', 'dbt'::resource_kind, 'A builder for statements about worth that come from wise mind rather than from mood.', 'Use it to help a client write worth statements that hold on hard days.', array['Adults']::text[], '20 minutes', 'The client lists the loudest harsh statement and writes a wise mind counterpart that is true on good and bad days, such as I am worth care even when I make mistakes. Rehearse reading them aloud. Revisit and revise weekly.', '[{"id": "f0", "type": "textarea", "label": "The harsh statement I hear most"}, {"id": "f1", "type": "textarea", "label": "What wise mind says instead"}, {"id": "f2", "type": "textarea", "label": "The statement I will keep"}, {"id": "f3", "type": "textarea", "label": "When I will read it"}, {"id": "f4", "type": "textarea", "label": "How I feel reading it"}]'::jsonb, array['self-esteem', 'core DBT', 'wise mind', 'self-talk']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('partner-as-cheerleader-goal-plan', 'Partner as Cheerleader Goal Plan', 'couples'::resource_kind, 'A plan where each partner names a goal and how the other can cheer it on.', 'Use it to help partners support each other''s confidence.', array['Couples']::text[], '30 minutes', 'Each partner shares a personal goal and what encouragement would help, and what would not. The other writes how they will cheer. Check in weekly. Encourage specific praise for effort.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my goal"}, {"id": "f1", "type": "textarea", "label": "Partner A: encouragement that helps"}, {"id": "f2", "type": "textarea", "label": "Partner B: my goal"}, {"id": "f3", "type": "textarea", "label": "Partner B: encouragement that helps"}, {"id": "f4", "type": "textarea", "label": "How we will check in each week"}]'::jsonb, array['self-esteem', 'couples', 'support', 'goal setting']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('my-strengths-treasure-chest-craft', 'My Strengths Treasure Chest Craft', 'kids'::resource_kind, 'A decorated box a child fills with cards naming their strengths and good moments.', 'Use it to help a child collect proof of what they are good at.', array['Children']::text[], '35 minutes', 'The child decorates a box and fills it with cards: things they are good at, things they did that took courage, and kind words others said. The parent adds a card when they notice effort. Praise actions and effort more than outcomes. Review the box in session.', '[{"id": "f0", "type": "textarea", "label": "Three things I am good at"}, {"id": "f1", "type": "textarea", "label": "Something brave I did"}, {"id": "f2", "type": "textarea", "label": "Kind words someone said about me"}, {"id": "f3", "type": "textarea", "label": "A card I want to add this week"}, {"id": "f4", "type": "textarea", "label": "Who helps me fill my chest"}]'::jsonb, array['self-esteem', 'children', 'strengths', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('joining-a-group-role-play-game', 'Joining a Group Role-Play Game', 'game'::resource_kind, 'A game where players practice walking up to a group and joining a conversation.', 'Use it to help players practice joining a group in a safe room.', array['Groups']::text[], '30 minutes', 'A small group chats while one player practices joining, using lines such as that sounds fun or mind if I join. Take turns, rate nerves and debrief. Let players choose how hard the scene is.', '[{"id": "f0", "type": "textarea", "label": "The line I used to join"}, {"id": "f1", "type": "textarea", "label": "How nervous I felt, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What the group did"}, {"id": "f3", "type": "textarea", "label": "What I would do differently"}, {"id": "f4", "type": "textarea", "label": "A real group I will try this with"}]'::jsonb, array['social anxiety', 'group', 'play', 'social skills']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('post-event-balanced-reflection-sheet', 'Post-Event Balanced Reflection Sheet', 'worksheet'::resource_kind, 'A sheet for looking back at a social event without picking apart every moment.', 'Use it to help a client replace post-event criticism with a balanced review.', array['Adults']::text[], '20 minutes', 'After an event the client writes what went as hoped, what was hard, what others actually did and one thing to try next time. Compare to the harsh replay. Set a time limit for reviewing.', '[{"id": "f0", "type": "textarea", "label": "What went the way I hoped"}, {"id": "f1", "type": "textarea", "label": "What was hard"}, {"id": "f2", "type": "textarea", "label": "What others actually did"}, {"id": "f3", "type": "textarea", "label": "A fair summary"}, {"id": "f4", "type": "textarea", "label": "One thing to try next time"}]'::jsonb, array['social anxiety', 'evidence', 'self-criticism']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('imagined-audience-recording-sheet', 'Imagined Audience Recording Sheet', 'cbt'::resource_kind, 'A sheet for guessing what the audience thinks and then checking what they did.', 'Use it to help a client test their guesses about how others see them.', array['Adults']::text[], '25 minutes', 'The client writes a guess about what people think, watches for evidence, and records what actually happened. Focus on observable behavior. Over several tries compare guesses with results.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What I guess others think"}, {"id": "f2", "type": "textarea", "label": "What I actually saw them do"}, {"id": "f3", "type": "textarea", "label": "What I make of the difference"}, {"id": "f4", "type": "textarea", "label": "What I will test next"}]'::jsonb, array['social anxiety', 'core CBT', 'thinking traps', 'perspective']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('imperfect-moment-acceptance-page', 'Imperfect Moment Acceptance Page', 'act'::resource_kind, 'A page for letting small social slips be there and carrying on with the conversation.', 'Use it to help a client carry on after a small social slip.', array['Adults']::text[], '25 minutes', 'The client names a feared slip, such as losing their words, and writes a line to say, such as give me a second. Rehearse in session on purpose. Notice self-judgment and practice returning to the conversation.', '[{"id": "f0", "type": "textarea", "label": "A slip I fear"}, {"id": "f1", "type": "textarea", "label": "A line I can say if it happens"}, {"id": "f2", "type": "textarea", "label": "What I will do with the self-judgment"}, {"id": "f3", "type": "textarea", "label": "How I will carry on"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I tried it"}]'::jsonb, array['social anxiety', 'core ACT', 'acceptance', 'self-compassion']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('saying-no-kindly-script-card', 'Saying No Kindly Script Card', 'dbt'::resource_kind, 'A card of short, kind ways to decline an invitation or request.', 'Use it to help a client practice declining without long explanations.', array['Adults']::text[], '20 minutes', 'The client writes several short no lines, such as thank you but I cannot make it. Role-play with you pushing gently. Rate nerves before and after, and choose one to try this week.', '[{"id": "f0", "type": "textarea", "label": "Something I find hard to say no to"}, {"id": "f1", "type": "textarea", "label": "Short ways to say no"}, {"id": "f2", "type": "textarea", "label": "The line I will use"}, {"id": "f3", "type": "textarea", "label": "How nervous I felt rehearsing"}, {"id": "f4", "type": "textarea", "label": "When I will try it"}]'::jsonb, array['social anxiety', 'core DBT', 'assertiveness', 'boundaries']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('anniversaries-and-holidays-grief-plan-for-two', 'Anniversaries and Holidays Grief Plan for Two', 'couples'::resource_kind, 'A plan for how partners will spend hard dates after a loss.', 'Use it to help partners plan hard dates together so neither is caught off guard.', array['Couples']::text[], '35 minutes', 'List the dates that are hard and for each ask what each wants, such as company, quiet or a ritual, and agree on a plan with a backup. Check in the day before. Revise after the date.', '[{"id": "f0", "type": "textarea", "label": "Dates that are hard"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I want on those days"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I want on those days"}, {"id": "f3", "type": "textarea", "label": "Our plan, with a backup"}, {"id": "f4", "type": "textarea", "label": "How we will check in"}]'::jsonb, array['grief and loss', 'couples', 'planning', 'support']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('feelings-after-a-loss-story-drawing-book', 'Feelings After a Loss Story Drawing Book', 'kids'::resource_kind, 'A small drawn book about feelings a child has had since a loss.', 'Use it to give a grieving child a way to show feelings in pictures.', array['Children']::text[], '35 minutes', 'The child draws pages such as a day I missed them and a day I felt okay. The parent looks through it with them and responds with warmth. Keep it at the child''s pace. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "A page about a day I missed them"}, {"id": "f1", "type": "textarea", "label": "A page about a day I felt okay"}, {"id": "f2", "type": "textarea", "label": "A page about a question I have"}, {"id": "f3", "type": "textarea", "label": "What helped me"}, {"id": "f4", "type": "textarea", "label": "Who I can show my book to"}]'::jsonb, array['grief and loss', 'children', 'art', 'emotion identification']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('remembering-stories-circle-game', 'Remembering Stories Circle Game', 'game'::resource_kind, 'A group game where members share a memory each turn using prompt cards.', 'Use it to help group members share and honor memories of someone they lost.', array['Groups']::text[], '40 minutes', 'Deal prompt cards such as a favorite meal they made or something that made them laugh. Each member shares if they like or passes. Others listen without advice. Debrief what it was like to remember and be heard, and offer a closing moment such as lighting a candle.', '[{"id": "f0", "type": "textarea", "label": "The card I chose"}, {"id": "f1", "type": "textarea", "label": "A memory I shared"}, {"id": "f2", "type": "textarea", "label": "What it felt like to share"}, {"id": "f3", "type": "textarea", "label": "What I heard that stayed with me"}, {"id": "f4", "type": "textarea", "label": "One way I will keep remembering"}]'::jsonb, array['grief and loss', 'group', 'play', 'connection']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('grief-waves-triggers-and-comforts-log', 'Grief Waves Triggers and Comforts Log', 'worksheet'::resource_kind, 'A log of when grief rises, what set it off and what comforted.', 'Use it to help a client see the rhythm of their grief and what helps.', array['Adults']::text[], 'One week', 'The client notes when a wave of grief came, the trigger, how strong it was and what comforted them. Review the pattern together, including anniversaries and quiet hours. There is no timeline for grief; focus on what helps and on small supports, not on getting past it.', '[{"id": "f0", "type": "textarea", "label": "When the wave came and what set it off"}, {"id": "f1", "type": "textarea", "label": "How strong it was, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I felt and thought"}, {"id": "f3", "type": "textarea", "label": "What comforted me"}, {"id": "f4", "type": "textarea", "label": "What I will do for myself tomorrow"}]'::jsonb, array['grief and loss', 'self-monitoring', 'triggers', 'support']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('unhelpful-grief-thoughts-gentle-review', 'Unhelpful Grief Thoughts Gentle Review', 'cbt'::resource_kind, 'A review of harsh thoughts like I should be over it, with kinder alternatives.', 'Use it to help a client soften harsh thoughts about how they should be grieving.', array['Adults']::text[], '25 minutes', 'The client writes thoughts such as I should have done more or I should be over it by now, then looks at what a close friend would say and writes a kinder alternative. Move gently, validate the pain first, and do not argue the guilt away too fast.', '[{"id": "f0", "type": "textarea", "label": "A harsh thought about my grief"}, {"id": "f1", "type": "textarea", "label": "How much I believe it, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f3", "type": "textarea", "label": "A kinder thought I can hold"}, {"id": "f4", "type": "textarea", "label": "How I will use it this week"}]'::jsonb, array['grief and loss', 'core CBT', 'guilt', 'self-compassion']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('hard-conversation-willingness-page', 'Hard Conversation Willingness Page', 'act'::resource_kind, 'A page for having a difficult talk with nerves, anger or fear present.', 'Use it to help a client start a hard conversation with feelings along.', array['Adults']::text[], '25 minutes', 'The client names the conversation, the value behind it, the feelings that tempt them to avoid, and the first sentence. Rehearse. Willingness means holding the feelings while speaking. Review after the talk.', '[{"id": "f0", "type": "textarea", "label": "The conversation I have been avoiding"}, {"id": "f1", "type": "textarea", "label": "The value behind it"}, {"id": "f2", "type": "textarea", "label": "The feelings that show up"}, {"id": "f3", "type": "textarea", "label": "My first sentence"}, {"id": "f4", "type": "textarea", "label": "What I will do with the feelings while I speak"}]'::jsonb, array['relationship issues', 'core ACT', 'willingness', 'communication']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('mindful-listening-turn-taking-card', 'Mindful Listening Turn-Taking Card', 'dbt'::resource_kind, 'A card for taking turns to listen with full attention and summarize before replying.', 'Use it to help a client practice listening one-mindfully in conversation.', array['Adults']::text[], '20 minutes', 'Pairs take turns speaking for a minute and listening without interrupting, then the listener summarizes before replying. Notice when attention drifts and bring it back. Debrief what it was like and when the client could try it.', '[{"id": "f0", "type": "textarea", "label": "What I noticed when I only listened"}, {"id": "f1", "type": "textarea", "label": "What I summarized back"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f3", "type": "textarea", "label": "How it felt to be listened to"}, {"id": "f4", "type": "textarea", "label": "A conversation to try this in"}]'::jsonb, array['relationship issues', 'core DBT', 'mindfulness', 'listening']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('topic-parking-lot-agreement', 'Topic Parking Lot Agreement', 'couples'::resource_kind, 'An agreement that lets partners park other topics so one conversation stays on track.', 'Use it to help partners keep a conflict conversation to one topic.', array['Couples']::text[], '25 minutes', 'Partners agree to write side topics on a shared list when they come up and return to them later at a set time. Practice with a small topic and a real parking lot. Review which topics were parked and how it felt to wait.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the topic we are working on"}, {"id": "f1", "type": "textarea", "label": "Partner B: a side topic I want to park"}, {"id": "f2", "type": "textarea", "label": "How we will write down parked topics"}, {"id": "f3", "type": "textarea", "label": "When we will come back to them"}, {"id": "f4", "type": "textarea", "label": "How it felt to wait"}]'::jsonb, array['relationship issues', 'couples', 'conflict', 'communication']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('kind-words-mailbox-craft', 'Kind Words Mailbox Craft', 'kids'::resource_kind, 'A decorated mailbox where children leave kind notes for family or friends.', 'Use it to help a child practice noticing and expressing kindness toward others.', array['Children']::text[], '30 minutes', 'The child decorates a box and writes or draws notes to people, such as thank you for sharing. The parent reads them out. Talk about what the notes say and how receivers feel. Keep notes about actions.', '[{"id": "f0", "type": "textarea", "label": "How I decorated my mailbox"}, {"id": "f1", "type": "textarea", "label": "A note I wrote and who for"}, {"id": "f2", "type": "textarea", "label": "How it felt to give it"}, {"id": "f3", "type": "textarea", "label": "A note someone gave me"}, {"id": "f4", "type": "textarea", "label": "Who I will write to next"}]'::jsonb, array['relationship issues', 'children', 'social skills', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('spot-the-respect-charades-game', 'Spot the Respect Charades Game', 'game'::resource_kind, 'A charades game where players act out respectful and disrespectful moments.', 'Use it to help players recognize respect in relationships through play.', array['Groups']::text[], '30 minutes', 'Players act out short scenes of respect or disrespect and others guess, then suggest a kinder version. Rotate turns and let players pass. Debrief what signs they notice and what they will practice.', '[{"id": "f0", "type": "textarea", "label": "A scene I acted"}, {"id": "f1", "type": "textarea", "label": "The sign that told us it was disrespectful"}, {"id": "f2", "type": "textarea", "label": "A kinder version"}, {"id": "f3", "type": "textarea", "label": "A sign of respect I want more of"}, {"id": "f4", "type": "textarea", "label": "What I will practice"}]'::jsonb, array['relationship issues', 'group', 'play', 'boundaries']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('daily-steadiness-anchors-planner', 'Daily Steadiness Anchors Planner', 'worksheet'::resource_kind, 'A planner for the small things that help a client feel steady each day.', 'Use it to help a client choose daily anchors that support steadiness.', array['Adults']::text[], '20 minutes', 'The client lists small daily anchors such as a morning routine, a call or a walk, and chooses times for them. Present-day only; do not ask for details of the past. Review and adjust each week.', '[{"id": "f0", "type": "textarea", "label": "An anchor for the morning"}, {"id": "f1", "type": "textarea", "label": "An anchor for the afternoon"}, {"id": "f2", "type": "textarea", "label": "An anchor for the evening"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "One I will keep this week"}]'::jsonb, array['sexual abuse', 'routines', 'stabilizing', 'support']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('self-blame-and-responsibility-gentle-check', 'Self-Blame and Responsibility Gentle Check', 'cbt'::resource_kind, 'A check on self-blame thoughts that does not ask for any account of events.', 'Use it to help a client look at self-blame thoughts at their own pace.', array['Adults']::text[], '25 minutes', 'Keep this to present-day thoughts such as it was my fault, held in general terms, without retelling anything. Ask what the client would say to someone else with the same thought, who holds responsibility for harm, and what a kinder statement sounds like. Let them stop at any point.', '[{"id": "f0", "type": "textarea", "label": "A self-blame thought that sometimes shows up"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend with that thought"}, {"id": "f3", "type": "textarea", "label": "A kinder thought I can try on"}, {"id": "f4", "type": "textarea", "label": "What helps me when the thought is loud"}]'::jsonb, array['sexual abuse', 'core CBT', 'guilt', 'stabilizing']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('reclaiming-choice-in-daily-life-values-page', 'Reclaiming Choice in Daily Life Values Page', 'act'::resource_kind, 'A page for choosing small daily actions that give a client a sense of agency.', 'Use it to help a client practice making choices that feel like their own.', array['Adults']::text[], '30 minutes', 'Start with values and small daily choices, such as what to eat, who to call or how to spend an hour, and let the client set the pace. Include grounding in the body in the present. Do not ask about the past. Check in about comfort throughout and stop whenever the client asks.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me"}, {"id": "f1", "type": "textarea", "label": "A small choice I made today that was mine"}, {"id": "f2", "type": "textarea", "label": "How my body felt when I chose"}, {"id": "f3", "type": "textarea", "label": "A choice I would like to make this week"}, {"id": "f4", "type": "textarea", "label": "A grounding step I can use"}]'::jsonb, array['sexual abuse', 'core ACT', 'values', 'grounding']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('grounding-with-senses-and-safe-place-image-card', 'Grounding with Senses and Safe Place Image Card', 'dbt'::resource_kind, 'A card of grounding skills and a safe place image drawn from the present.', 'Use it to help a client steady themselves when reminders arrive.', array['Adults']::text[], '25 minutes', 'Build the card with the client: five senses grounding, feet on the floor and a safe place that is real or imagined, chosen by them. Practice in session when calm. Offer alternatives if closing the eyes is uncomfortable. The card is for stabilizing, not for processing.', '[{"id": "f0", "type": "textarea", "label": "Five things I can see right now"}, {"id": "f1", "type": "textarea", "label": "Something I can touch"}, {"id": "f2", "type": "textarea", "label": "Something I can hear"}, {"id": "f3", "type": "textarea", "label": "My safe place in a few words"}, {"id": "f4", "type": "textarea", "label": "Who I could contact if I need support"}]'::jsonb, array['sexual abuse', 'core DBT', 'grounding', 'stabilizing']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('partner-self-care-and-limits-plan', 'Partner Self-Care and Limits Plan', 'couples'::resource_kind, 'A plan for how a supporting partner takes care of themselves and keeps their limits.', 'Use it to help a supporting partner care for themselves while staying present.', array['Couples']::text[], '30 minutes', 'The supporting partner writes what they need, such as time with friends, and limits they will keep. The partner who has experienced harm hears the plan and says what they need from it. Nobody recounts anything. Revisit regularly.', '[{"id": "f0", "type": "textarea", "label": "Partner B: what I need to stay well"}, {"id": "f1", "type": "textarea", "label": "Partner B: limits I will keep"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I need from this plan"}, {"id": "f3", "type": "textarea", "label": "How we will tell each other when we need a break"}, {"id": "f4", "type": "textarea", "label": "When we will revisit this"}]'::jsonb, array['sexual abuse', 'couples', 'boundaries', 'support']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('feelings-thermometer-skill-match-poster', 'Feelings Thermometer Skill Match Poster', 'kids'::resource_kind, 'A poster pairing each level of a feelings thermometer with a skill the child picks.', 'Use it to help a child match skills to how big the feeling is.', array['Children']::text[], '35 minutes', 'The child draws a thermometer and writes skills at each level, such as a deep breath at medium and a break at high. The parent learns the poster and prompts the child to check their level. Practice a skill at each level.', '[{"id": "f0", "type": "textarea", "label": "A skill for a little feeling"}, {"id": "f1", "type": "textarea", "label": "A skill for a medium feeling"}, {"id": "f2", "type": "textarea", "label": "A skill for a big feeling"}, {"id": "f3", "type": "textarea", "label": "How I check my level"}, {"id": "f4", "type": "textarea", "label": "Who helps me"}]'::jsonb, array['coping skills', 'children', 'regulation', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('coping-skills-trade-market-game', 'Coping Skills Trade Market Game', 'game'::resource_kind, 'A game where players trade skill cards after explaining how they work.', 'Use it to help a group share and learn each other''s coping skills.', array['Groups']::text[], '30 minutes', 'Each player writes a skill on a card and explains it, then trades with another player who promises to try it this week. Report back next session. Debrief what players got and gave.', '[{"id": "f0", "type": "textarea", "label": "The skill I traded away"}, {"id": "f1", "type": "textarea", "label": "The skill I received"}, {"id": "f2", "type": "textarea", "label": "Why I picked it"}, {"id": "f3", "type": "textarea", "label": "When I will try it"}, {"id": "f4", "type": "textarea", "label": "What I will report back"}]'::jsonb, array['coping skills', 'group', 'play', 'skills']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('weekly-skill-practice-schedule', 'Weekly Skill Practice Schedule', 'worksheet'::resource_kind, 'A weekly schedule where a client plans which skill to practice on which day.', 'Use it to help a client spread skill practice through the week.', array['Adults']::text[], '20 minutes', 'The client picks a skill for each day, a time, and a cue. At the end of the week they note which fit and which did not. Keep it light and flexible.', '[{"id": "f0", "type": "textarea", "label": "The skill I picked for each day"}, {"id": "f1", "type": "textarea", "label": "The time and cue for each"}, {"id": "f2", "type": "textarea", "label": "Which skills I practiced"}, {"id": "f3", "type": "textarea", "label": "Which did not fit"}, {"id": "f4", "type": "textarea", "label": "What I will change next week"}]'::jsonb, array['coping skills', 'skills', 'planning', 'routines']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('coping-plan-if-then-cards', 'Coping Plan If-Then Cards', 'cbt'::resource_kind, 'A set of if-then cards that link a trigger situation to a planned coping step.', 'Use it to help a client decide in advance what they will do in a hard moment.', array['Adults']::text[], '25 minutes', 'The client writes if-then statements, such as if I feel tight in my chest at work, then I will step outside and breathe out slowly. Keep each plan specific and doable. Role-play one in session. Review which plans were used and why others were not.', '[{"id": "f0", "type": "textarea", "label": "If this happens"}, {"id": "f1", "type": "textarea", "label": "Then I will do this"}, {"id": "f2", "type": "textarea", "label": "If this other thing happens"}, {"id": "f3", "type": "textarea", "label": "Then I will do this"}, {"id": "f4", "type": "textarea", "label": "Where I will keep these cards"}]'::jsonb, array['coping skills', 'core CBT', 'planning', 'skills']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('hooked-and-unhooked-moments-review-page', 'Hooked and Unhooked Moments Review Page', 'act'::resource_kind, 'A page for describing a recent moment of being hooked by a thought or feeling and what unhooking looked like.', 'Use it to help a client notice when they are hooked and what helps them unhook.', array['Adults']::text[], '25 minutes', 'The client describes a moment where a thought or feeling pulled them away from what matters, what they did and what an unhooked response would have been. Look for cues they can catch. Practice with a recent example.', '[{"id": "f0", "type": "textarea", "label": "A moment I got hooked"}, {"id": "f1", "type": "textarea", "label": "What hooked me"}, {"id": "f2", "type": "textarea", "label": "What I did while hooked"}, {"id": "f3", "type": "textarea", "label": "What unhooked me, or could have"}, {"id": "f4", "type": "textarea", "label": "The cue I will watch for"}]'::jsonb, array['coping skills', 'core ACT', 'defusion', 'workability']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('muscle-release-and-calm-imagery-card', 'Muscle Release and Calm Imagery Card', 'dbt'::resource_kind, 'A card pairing muscle relaxation with calm imagery to use before facing a fear.', 'Use it to help a client settle the body before approaching something feared.', array['Adults']::text[], '25 minutes', 'Teach tensing and releasing muscle groups in order, then a calm image. Practice in session and rate tension before and after. The client uses it before an approach step, not instead of one. Check for any physical limits.', '[{"id": "f0", "type": "textarea", "label": "Where I held tension"}, {"id": "f1", "type": "textarea", "label": "The calm image I picked"}, {"id": "f2", "type": "textarea", "label": "Tension before and after, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "When I will use it before a step"}, {"id": "f4", "type": "textarea", "label": "The step I will take"}]'::jsonb, array['phobias', 'core DBT', 'self-soothing', 'distress tolerance']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('supporting-a-partner-through-fear-plan', 'Supporting a Partner Through Fear Plan', 'couples'::resource_kind, 'A plan for a partner to support practice without pushing or protecting too much.', 'Use it to help a partner cheer practice on without taking over or pushing.', array['Couples']::text[], '30 minutes', 'The partner with the fear says what helps and what does not, such as I want company, not rescue. The other partner plans how to encourage without doing the avoiding for them or pressing. Agree on how to handle a hard day. Review the plan after the first practice.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps when I practice"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I will support without pushing"}, {"id": "f3", "type": "textarea", "label": "How we will handle a hard day"}, {"id": "f4", "type": "textarea", "label": "What we will do to celebrate a step"}]'::jsonb, array['phobias', 'couples', 'support', 'exposure']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('fear-monster-makeover-drawing', 'Fear Monster Makeover Drawing', 'kids'::resource_kind, 'A drawing activity where a child redraws a scary thing as silly or small.', 'Use it to help a child feel more in charge of a feared thing through play.', array['Children']::text[], '30 minutes', 'The child draws the feared thing, then makes it look silly with funny shoes or a small size. Talk about how it feels looking at the changed drawing. The parent learns to praise brave steps and does not force exposure. Choose a next small step together.', '[{"id": "f0", "type": "textarea", "label": "My drawing of the feared thing"}, {"id": "f1", "type": "textarea", "label": "How I changed it"}, {"id": "f2", "type": "textarea", "label": "How I feel looking at my new drawing"}, {"id": "f3", "type": "textarea", "label": "A brave step I could try"}, {"id": "f4", "type": "textarea", "label": "Who is with me when I try it"}]'::jsonb, array['phobias', 'children', 'exposure', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('courage-ladder-board-game', 'Courage Ladder Board Game', 'game'::resource_kind, 'A board game where players move up a ladder of small brave tasks.', 'Use it to help a group cheer each other through planned brave steps.', array['Groups']::text[], '35 minutes', 'Players write a ladder of small brave tasks and take turns moving a token up, with the group cheering each step. Players can choose an easier task if needed. Debrief what made a step possible and what they will try this week.', '[{"id": "f0", "type": "textarea", "label": "The brave step I chose"}, {"id": "f1", "type": "textarea", "label": "How scared I felt, 0 to 10, before and after"}, {"id": "f2", "type": "textarea", "label": "What helped me do it"}, {"id": "f3", "type": "textarea", "label": "What the group did that helped"}, {"id": "f4", "type": "textarea", "label": "My next step this week"}]'::jsonb, array['phobias', 'group', 'play', 'hierarchy']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('fear-facts-and-imagination-sorting-page', 'Fear Facts and Imagination Sorting Page', 'worksheet'::resource_kind, 'A sorting page that separates what is known about a feared thing from what is imagined.', 'Use it to help a client tell facts about a feared thing from what the mind adds.', array['Adults']::text[], '20 minutes', 'Have the client list everything they believe about the feared thing, then sort into facts they can check and things the mind adds. Check facts together and plan a way to learn more. Do not force a view; the sorting is a first step toward approaching.', '[{"id": "f0", "type": "textarea", "label": "What I believe about the thing I fear"}, {"id": "f1", "type": "textarea", "label": "Facts I can check"}, {"id": "f2", "type": "textarea", "label": "Things my mind adds"}, {"id": "f3", "type": "textarea", "label": "How I could learn more"}, {"id": "f4", "type": "textarea", "label": "A small step I can take next"}]'::jsonb, array['phobias', 'evidence', 'avoidance']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('body-image-thought-trap-notebook-page', 'Body Image Thought Trap Notebook Page', 'cbt'::resource_kind, 'A page for catching harsh thoughts about appearance and testing kinder ones.', 'Use it to help a client notice harsh thoughts about appearance and try other thoughts.', array['Adults']::text[], '25 minutes', 'The client writes the situation, the harsh thought, the feeling, and a more balanced thought. Include what a friend would say. Avoid reviewing or commenting on how the client looks; the focus is the thought, not the body. Practice once in session on a recent example.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The harsh thought about how I look"}, {"id": "f2", "type": "textarea", "label": "How I felt and what I did"}, {"id": "f3", "type": "textarea", "label": "What a friend would say"}, {"id": "f4", "type": "textarea", "label": "A balanced thought I can try"}]'::jsonb, array['body image', 'core CBT', 'thinking traps', 'self-talk']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('valued-living-instead-of-hiding-page', 'Valued Living Instead of Hiding Page', 'act'::resource_kind, 'A page for taking part in valued activities instead of avoiding them because of appearance worries.', 'Use it to help a client do what matters while worries about looks come along.', array['Adults']::text[], '30 minutes', 'Ask which activities the client skips or does halfheartedly, such as photos, swimming or social events, and which value they connect to. Choose one and practice taking part with appearance thoughts present, using defusion. Review what happened and what mattered.', '[{"id": "f0", "type": "textarea", "label": "An activity I avoid because of how I look"}, {"id": "f1", "type": "textarea", "label": "The value behind it"}, {"id": "f2", "type": "textarea", "label": "The thoughts that show up"}, {"id": "f3", "type": "textarea", "label": "How I will carry them and take part"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['body image', 'core ACT', 'values', 'avoidance']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('wise-mind-body-appreciation-skill-card', 'Wise Mind Body Appreciation Skill Card', 'dbt'::resource_kind, 'A card for noticing what the body does and practicing neutral, respectful attention.', 'Use it to help a client practice respectful attention to their body.', array['Adults']::text[], '20 minutes', 'Have the client name things their body does for them, such as walking, hugging or breathing, and a kind or neutral word for it. Pair with mindful attention to a sensation without judgment. Skip any focus on looks. Ask for a daily practice of one sentence.', '[{"id": "f0", "type": "textarea", "label": "Something my body does for me today"}, {"id": "f1", "type": "textarea", "label": "A neutral or kind word for my body"}, {"id": "f2", "type": "textarea", "label": "A sensation I noticed without judging"}, {"id": "f3", "type": "textarea", "label": "What a wise mind says about my body"}, {"id": "f4", "type": "textarea", "label": "When I will practice this"}]'::jsonb, array['body image', 'core DBT', 'wise mind', 'body awareness']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('partner-words-about-bodies-agreement', 'Partner Words About Bodies Agreement', 'couples'::resource_kind, 'An agreement on how partners speak about their own and each other''s bodies.', 'Use it to help partners agree on kind and respectful talk about bodies.', array['Couples']::text[], '30 minutes', 'Each partner shares which comments feel supportive or hurtful, including jokes. They agree on words to avoid, on what to say instead and on a way to flag a comment that stings. Emphasize that appreciation can focus on character and shared moments. Review after a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: comments that hurt"}, {"id": "f1", "type": "textarea", "label": "Partner B: comments that hurt"}, {"id": "f2", "type": "textarea", "label": "Words and jokes we agree to leave out"}, {"id": "f3", "type": "textarea", "label": "What we can say instead"}, {"id": "f4", "type": "textarea", "label": "How we will flag a comment that stings"}]'::jsonb, array['body image', 'couples', 'communication', 'appreciation']::text[], '2026-10-14T15:00:00+00:00'::timestamptz),
  ('body-thank-you-notes-craft', 'Body Thank-You Notes Craft', 'kids'::resource_kind, 'A craft where a child writes thank-you notes to parts of their body for what they do.', 'Use it to help a child feel thankful for their body and what it does.', array['Children']::text[], '30 minutes', 'The child writes or draws notes such as thank you legs for running. The parent joins in and avoids comments about looks. Display the notes. Talk about how the body helps them play and learn.', '[{"id": "f0", "type": "textarea", "label": "A thank-you note to my legs"}, {"id": "f1", "type": "textarea", "label": "A thank-you note to my hands"}, {"id": "f2", "type": "textarea", "label": "A thank-you note to another body part"}, {"id": "f3", "type": "textarea", "label": "What I like doing most"}, {"id": "f4", "type": "textarea", "label": "Who I will show my notes to"}]'::jsonb, array['body image', 'children', 'gratitude', 'art']::text[], '2026-10-14T15:00:00+00:00'::timestamptz)
